insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Edat mitjana: Corts, pactisme i Diputació del General"},{"n":"2","title":"Època moderna: Casp, Observança, 1640 i 1714"},{"n":"3","title":"Segle XX: Mancomunitat, República i Generalitat a l''exili"},{"n":"4","title":"Transició i Estatuts (1979, 2006)"},{"n":"5","title":"Símbols nacionals i presidents recents"}]'::jsonb, '["Diputació del General, 1283 Generalitat, Història de la Generalitat: «Aquest sistema establia que el sobirà no podia promulgar constitucions ni exigir impostos generals sense l’autorització dels tres estaments o braços —el militar, l’eclesiàstic i el reial o popular— reunits en Corts.»","Diputació del General, Pesta Negra Generalitat, Història de la Generalitat: «Durant el regnat de Pere el Cerimoniós, Catalunya va viure una crisi econòmica i demogràfica a causa de la Pesta Negra de 1348.»","Diputació del General, seu Generalitat, Història de la Generalitat: «La institució es va instal·lar a les cases del carrer de Sant Honorat, que amb el temps es van convertir en el Palau de la Generalitat.»","Compromís de Casp, 1412 Generalitat, Història de la Generalitat: «Quan el Casal de Barcelona es va extingir el 1410, es va obrir un període d’incertesa política conegut com Interregne, que va acabar amb el Compromís de Casp de 1412.»","Val d''Aran, 1410 Generalitat, Història de la Generalitat: «Un exemple és la integració voluntària de la Val d’Aran (un territori de senyoria reial autònom) al Principat el 1410»","Insaculació, 1455 Generalitat, Història de la Generalitat: «El 1455 es va introduir un sistema mixt que combinava la cooptació amb la insaculació (que consistia a introduir en un sac els noms dels candidats, que eren escollits al atzar per una ma innocent»","Constitució de l''Observança, 1481 Generalitat, Història de la Generalitat: «establint la Constitució de l’Observança, que començava dient: \"Poc valdria fer lleis i constitucions si no fossin respectades per nosaltres i els nostres oficials\".»","Pacte de Ceret, 1640 Generalitat, Història de la Generalitat: «La Diputació va signar el pacte de Ceret amb França el 7 de setembre de 1640 per rebre suport militar»","Tractat dels Pirineus, 1659 Generalitat, Història de la Generalitat: «Finalment, el Tractat dels Pirineus de 1659 va sancionar l’annexió a França del Rosselló, el Conflent, el Vallespir i part de la Cerdanya.»","11 de setembre de 1714 Generalitat, Història de la Generalitat: «L’assalt definitiu de la ciutat va tenir lloc l’11 de setembre: Casanova va quedar ferit i Villarroel va cridar a la capitulació.»","Darrer reducte, 1714 Generalitat, Història de la Generalitat: «El darrer reducte de resistència, Cardona, va caure pocs dies després.»","Decret de Nova Planta, 1716 Generalitat, Història de la Generalitat: «Amb el Decret de Nova Planta, publicat a Catalunya el 16 de gener de 1716, Felip V va establir un règim polític que excloïa la representació de la societat catalana»","Mancomunitat Generalitat, Història de la Generalitat: «Hi ha un nexe que uneix els primers triomfs electorals del catalanisme polític el 1901-1907 amb la primera experiència d''autogovern català, la Mancomunitat de 1914-1925.»","Generalitat provisional, 1931 Generalitat, Història de la Generalitat: «Arran dels esdeveniments d''abril de 1931 quedà constituïda, amb caràcter provisional, la Generalitat de Catalunya, presidida per Francesc Macià»","Primer Parlament, 1932 Generalitat, Història de la Generalitat: «que fou elegit per primera i única vegada dins l''etapa republicana el 20 de novembre de 1932.»","Lluís Companys, 1940 Generalitat, Història de la Generalitat: «el president de la Generalitat va ser jutjat en un consell de guerra sumaríssim i afusellat al castell de Montjuïc el dia 15 d''octubre de 1940.»","Tarradellas, 1977 Generalitat, Història de la Generalitat: «el decret de 29 de setembre de 1977 reconeixia com a president de la Generalitat Josep Tarradellas, l''única autoritat republicana que retornà d''un exili de quaranta anys»","Estatut de 1979 Generalitat, Història de la Generalitat: «Aquesta, denominada Comissió dels Vint es reuní al parador de Sau»","Símbols nacionals, EAC art. 8 EAC: «El himno de Cataluña es «Els segadors».»","Presidents, 2024 Generalitat, Història de la Generalitat: «Salvador Illa va ser investit 133è president de la Generalitat el 8 d’agost de 2024»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Edat mitjana: les Corts i el sistema pactista (1283)","blocks":[{"text":"El punt de partida de les institucions catalanes medievals és el pactisme, la idea que el poder del rei no és absolut sinó que s''ha de pactar amb el país. A la Cort de Barcelona de 1283, presidida pel rei Pere el Gran, es va implantar aquest sistema. Des d''aleshores el sobirà no podia promulgar constitucions (és a dir, lleis) ni exigir impostos generals sense l''autorització dels tres estaments reunits en Corts. Aquests tres estaments o braços eren el militar, l''eclesiàstic i el reial o popular. Per a l''examen convé recordar la tríada «constitucions i impostos» i els tres braços.","refs":[{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"A la Cort de Barcelona de 1283, presidida pel rei Pere el Gran, es va implantar el sistema pactista. Aquest sistema establia que el sobirà no podia promulgar constitucions ni exigir impostos generals sense l’autorització dels tres estaments o braços —el militar, l’eclesiàstic i el reial o popular— reunits en Corts."}]},{"text":"L''Estatut d''autonomia vigent recull aquesta tradició al preàmbul: hi diu que el poble de Catalunya ha mantingut al llarg dels segles una vocació d''autogovern encarnada en institucions pròpies com la Generalitat, creada el 1359 a les Corts de Cervera, i en un ordenament jurídic propi recollit, entre altres compilacions, a les «Constitucions i altres drets de Catalunya».","refs":[{"ref":"Preàmbul de l''EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"encarnada en instituciones propias como la Generalitat -que fue creada en 1359 en las Cortes de Cervera- y en un ordenamiento jurídico específico recogido, entre otras recopilaciones de normas, en las «Constitucions i altres drets de Catalunya»."}]}]},{"n":"2","title":"La Diputació del General: origen i seu","blocks":[{"text":"La Diputació del General (l''origen de l''actual Generalitat) es va consolidar al segle XIV en un context de crisi. Durant el regnat de Pere el Cerimoniós, Catalunya va patir una greu crisi econòmica i demogràfica a causa de la Pesta Negra de 1348. Aquesta situació va portar a la creació definitiva d''una Diputació del General només per a Catalunya, amb seu a Barcelona. La institució es va instal·lar a les cases del carrer de Sant Honorat, que amb el temps es van convertir en el Palau de la Generalitat; per tant, quan una pregunta parli de l''origen del Palau, la resposta és el carrer de Sant Honorat.","refs":[{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Durant el regnat de Pere el Cerimoniós, Catalunya va viure una crisi econòmica i demogràfica a causa de la Pesta Negra de 1348."},{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Això va portar a la creació definitiva d’una Diputació del General només per a Catalunya, amb seu a Barcelona. La institució es va instal·lar a les cases del carrer de Sant Honorat, que amb el temps es van convertir en el Palau de la Generalitat."}]}]},{"n":"3","title":"1410: l''Interregne, el Compromís de Casp i la Val d''Aran","blocks":[{"text":"L''any 1410 és clau. El rei Martí l''Humà va morir aquell any sense descendència i, amb ell, es va extingir el Casal de Barcelona. Es va obrir així un període d''incertesa política conegut com a Interregne, en què els diputats van assumir un paper polític per gestionar la situació i decidir qui seria el nou rei. L''Interregne va acabar amb el Compromís de Casp de 1412.","refs":[{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Quan el Casal de Barcelona es va extingir el 1410, es va obrir un període d’incertesa política conegut com Interregne, que va acabar amb el Compromís de Casp de 1412."},{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Per això, quan el rei Martí l’Humà va morir el 1410 sense descendència, els diputats van assumir un paper polític per gestionar l’Interregne i decidir qui seria el nou rei."}]},{"text":"El mateix 1410 la Val d''Aran, que era un territori de senyoria reial autònom, es va integrar voluntàriament al Principat. A canvi de protecció militar, l''Aran es comprometia a contribuir econòmicament a la Diputació. Avui l''Estatut reconeix l''Aran com una realitat occitana amb identitat cultural, històrica, geogràfica i lingüística pròpia, i com a entitat territorial singular dins de Catalunya, amb un règim jurídic especial.","refs":[{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Un exemple és la integració voluntària de la Val d’Aran (un territori de senyoria reial autònom) al Principat el 1410, amb el compromís de contribuir econòmicament a la Diputació a canvi de protecció militar."},{"ref":"Art. 11.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"reconocen a Arán como una realidad occitana dotada de identidad cultural, histórica, geográfica y lingüística, defendida por los araneses a lo largo de los siglos. El presente Estatuto reconoce, ampara y respeta esta singularidad y reconoce Arán como entidad territorial singular dentro de Cataluña"}]}]},{"n":"4","title":"Segle XV: la insaculació (1455) i la Constitució de l''Observança (1481)","blocks":[{"text":"Al segle XV es va reformar la manera d''escollir els càrrecs de la Diputació. El 1455 es va introduir un sistema mixt que combinava la cooptació (els mateixos membres escullen els nous) amb la insaculació. La insaculació consistia a introduir en un sac els noms dels candidats, que després eren escollits a l''atzar per una mà innocent. És a dir: sac i sorteig, per evitar que un grup controlés els nomenaments.","refs":[{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"El 1455 es va introduir un sistema mixt que combinava la cooptació amb la insaculació (que consistia a introduir en un sac els noms dels candidats, que eren escollits al atzar per una ma innocent"}]},{"text":"A les Corts Generals de Barcelona de 1481, el rei Ferran II va reafirmar el seu compromís amb el pactisme i va establir la Constitució de l''Observança. Aquesta norma obligava el mateix rei i els seus oficials a respectar les lleis, i començava amb una frase molt citada: «Poc valdria fer lleis i constitucions si no fossin respectades per nosaltres i els nostres oficials». La idea de fons és que la llei obliga també qui governa.","refs":[{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"A les Corts Generals de Barcelona de 1481, el rei Ferran II va reafirmar el seu compromís amb el sistema pactista, establint la Constitució de l’Observança, que començava dient: \"Poc valdria fer lleis i constitucions si no fossin respectades per nosaltres i els nostres oficials\"."}]}]},{"n":"5","title":"Època moderna: 1640, el pacte de Ceret i el Tractat dels Pirineus","blocks":[{"text":"Al segle XVII es va produir una ruptura amb la Monarquia Hispànica. El 7 de setembre de 1640 la Diputació va signar el pacte de Ceret amb França. Amb aquest pacte buscava tres coses: rebre suport militar, separar-se de la Monarquia Hispànica i constituir-se com una república lliure sota la protecció del rei francès.","refs":[{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"La Diputació va signar el pacte de Ceret amb França el 7 de setembre de 1640 per rebre suport militar, separar-se de la Monarquia Hispànica i constituir-se com una república lliure sota la protecció del rei francès."}]},{"text":"El conflicte va tenir una conseqüència territorial permanent. El Tractat dels Pirineus de 1659 va sancionar l''annexió a França del Rosselló, el Conflent, el Vallespir i part de la Cerdanya. Recorda els quatre noms i el matís «part de» la Cerdanya: no tota la comarca va passar a França.","refs":[{"ref":"Història de la Generalitat (Diputació del General)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Finalment, el Tractat dels Pirineus de 1659 va sancionar l’annexió a França del Rosselló, el Conflent, el Vallespir i part de la Cerdanya."}]}]},{"n":"6","title":"1714 i el Decret de Nova Planta (1716)","blocks":[{"text":"L''abril de 1714 va començar el setge de Barcelona. La ciutat va ser defensada per les companyies creades pels gremis, sota la direcció d''Antoni Villarroel i Rafael Casanova. L''assalt definitiu va tenir lloc l''11 de setembre: Casanova va quedar ferit i Villarroel va cridar a la capitulació. El darrer reducte de resistència, Cardona, va caure pocs dies després. Aquesta data és l''origen de la Diada: l''Estatut fixa que la festa de Catalunya és l''Onze de Setembre.","refs":[{"ref":"Història de la Generalitat (Nova Planta)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"A l’abril de 1714 va començar el setge de Barcelona, que va ser defensada per les companyies creades pels gremis, sota la direcció d’Antoni Villarroel i Rafael Casanova. L’assalt definitiu de la ciutat va tenir lloc l’11 de setembre: Casanova va quedar ferit i Villarroel va cridar a la capitulació. El darrer reducte de resistència, Cardona, va caure pocs dies després."},{"ref":"Art. 8.3 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La fiesta de Cataluña es el Día Once de Septiembre."}]},{"text":"Després de la derrota, Felip V va imposar el Decret de Nova Planta, publicat a Catalunya el 16 de gener de 1716. El nou règim excloïa la representació de la societat catalana i reforçava la supremacia de les autoritats militars sobre les civils. El preàmbul de l''Estatut ho resumeix dient que, després de 1714, hi ha hagut diversos intents de recuperar les institucions d''autogovern.","refs":[{"ref":"Història de la Generalitat (Nova Planta)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Amb el Decret de Nova Planta, publicat a Catalunya el 16 de gener de 1716, Felip V va establir un règim polític que excloïa la representació de la societat catalana i reforçava la supremacia de les autoritats militars sobre les civils."},{"ref":"Preàmbul de l''EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Después de 1714, han sido varios los intentos de recuperación de las instituciones de autogobierno."}]}]},{"n":"7","title":"Segle XX: el catalanisme polític i la Mancomunitat (1914-1925)","blocks":[{"text":"Al segle XX travessa la història un fil d''afirmació de la personalitat política de Catalunya, sovint enfrontat a tendències centralitzadores, sobretot durant les dues dictadures: la del general Primo de Rivera (1923-1930) i la del general Franco (1939-1975). Els primers triomfs electorals del catalanisme polític, entre 1901 i 1907, enllacen amb la primera experiència d''autogovern català del segle: la Mancomunitat, que va existir entre 1914 i 1925. L''Estatut vigent la cita com una de les fites destacades de la recuperació de l''autogovern.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Un fil històric d''afirmació de la personalitat política de Catalunya travessa tot el segle XX, enfrontat sovint amb tendències centralitzadores al conjunt de l’Estat, especialment remarcada a les dues dictadures: la del general Primo de Rivera (1923-1930) i la del general Franco (1939-1975)."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Hi ha un nexe que uneix els primers triomfs electorals del catalanisme polític el 1901-1907 amb la primera experiència d''autogovern català, la Mancomunitat de 1914-1925."},{"ref":"Preàmbul de l''EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"En este itinerario histórico constituyen hitos destacados, entre otros, la Mancomunidad de 1914, la recuperación de la Generalitat con el Estatuto de 1932"}]}]},{"n":"8","title":"La Segona República: Generalitat provisional, Estatut de 1932 i Parlament","blocks":[{"text":"Les eleccions municipals del 12 d''abril de 1931 van provocar la caiguda de la monarquia. A Catalunya va guanyar Esquerra Republicana de Catalunya, i el seu líder, Francesc Macià, va proclamar unilateralment el dia 14 «la República catalana com a Estat de la Federació Ibèrica», poques hores abans que a Madrid es proclamés la Segona República espanyola.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Arran de les eleccions municipals de 12 d''abril de 1931, que determinaren la caiguda de la monarquia, Francesc Macià, líder d''Esquerra Republicana de Catalunya -partit triomfador a Catalunya- proclamà de manera unilateral «la República catalana com a Estat de la Federació Ibèrica» el dia 14, poques hores abans que a Madrid es procedís a proclamar la Segona República espanyola."}]},{"text":"Arran d''aquells fets es va constituir, amb caràcter provisional, la Generalitat de Catalunya, presidida per Francesc Macià. Tenia un consell o govern, una assemblea de representants dels municipis anomenada Diputació Provisional de la Generalitat i uns comissaris que, com a delegats del govern, s''encarregaven dels serveis de les diputacions provincials suprimides de Girona, Tarragona i Lleida.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Arran dels esdeveniments d''abril de 1931 quedà constituïda, amb caràcter provisional, la Generalitat de Catalunya, presidida per Francesc Macià i composta per un consell o govern, una assemblea de representants dels municipis -denominada Diputació Provisional de la Generalitat- i uns comissaris"}]},{"text":"L''Estatut de Núria va haver de ser adaptat i, un cop reformat, es va promulgar el 15 de setembre de 1932 sense tornar-lo a sotmetre a plebiscit. El nou Parlament de Catalunya, encarregat de desenvolupar aquest marc, va ser elegit per primera i única vegada en l''etapa republicana el 20 de novembre de 1932. A finals de 1932 quedà configurada la Generalitat definitiva: Macià, ratificat com a president, i Lluís Companys, nomenat president del Parlament.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Calgué, en conseqüència, adaptar l''Estatut de Núria, que, un cop reformat, fou promulgat el 15 de setembre de 1932 sense sotmetre''l de nou al plebiscit dels catalans."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"La regulació i desenvolupament d''aquest marc institucional quedava encarregat al nou Parlament de Catalunya, que fou elegit per primera i única vegada dins l''etapa republicana el 20 de novembre de 1932."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"A la darreria de 1932, amb l''aprovació de l''Estatut i les eleccions al Parlament, quedà configurada la Generalitat definitiva, amb Francesc Macià ratificat com a president i Lluís Companys nomenat president del Parlament."}]},{"text":"Macià va morir el 25 de desembre de 1933 i la presidència va passar a Companys, que la va exercir fins al final de la Guerra Civil, amb el parèntesi de la suspensió de l''Estatut entre l''octubre de 1934 i el febrer de 1936 (la font parla del «primer» i del «segon» en referència a tots dos). El setembre de 1936 es va formar un govern d''unitat amb forces d''esquerra encapçalat per Josep Tarradellas com a conseller primer.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"A la mort del primer, el 25 de desembre de 1933, correspongué la presidència de la Generalitat al segon, que l''exercí fins al final de la Guerra Civil, excepte el parèntesi de suspensió de l''Estatut que va d''octubre de 1934 a febrer de 1936."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"El setembre de 1936 es formà un govern d''unitat amb forces d''esquerra encapçalat per Josep Tarradellas com a conseller primer."}]}]},{"n":"9","title":"Guerra, abolició i Generalitat a l''exili","blocks":[{"text":"El 5 d''abril de 1938, amb el desenllaç de la guerra ja a la vista, el general Franco va signar a Burgos un decret que abolia la Generalitat. Va començar un període sense democràcia ni drets nacionals catalans que va durar fins a la mort del dictador, el 20 de novembre de 1975.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"El dia 5 d''abril de 1938, a la vista ja del desenllaç de la guerra civil, el general Franco signà a Burgos un decret que abolia la Generalitat de Catalunya"},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"encetaren un període de privació de la democràcia i els drets nacionals catalans que havia de durar fins a la mort del dictador el 20 de novembre de 1975."}]},{"text":"El president Lluís Companys va ser traslladat primer a Madrid i després a Barcelona, jutjat en un consell de guerra sumaríssim i afusellat al castell de Montjuïc el 15 d''octubre de 1940. A la seva mort, Josep Irla, president del Parlament, va assumir interinament la presidència de la Generalitat a l''exili.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Traslladat primer a Madrid i després a Barcelona, el president de la Generalitat va ser jutjat en un consell de guerra sumaríssim i afusellat al castell de Montjuïc el dia 15 d''octubre de 1940."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"A la mort de Companys, Josep Irla, president del Parlament de Catalunya, va assumir interinament el càrrec de president de la Generalitat a l''exili"}]},{"text":"El 1954, arran d''una dimissió a la presidència a l''exili, un grup d''antics diputats es va reunir a l''ambaixada espanyola a Mèxic, que conservaven les autoritats republicanes exiliades perquè el govern mexicà no havia reconegut el règim de Franco. Per mantenir la continuïtat institucional, van elegir president Josep Tarradellas, que havia estat conseller primer i conseller de Finances.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Arran de la seva dimissió el 1954, un grup d''antics diputats del Parlament català, reunit a l''ambaixada espanyola a Mèxic (conservada per les autoritats republicanes exiliades perquè el govern mexicà no havia reconegut el règim de Franco) decidí mantenir la continuïtat institucional i va elegir president de la Generalitat Josep Tarradellas"}]}]},{"n":"10","title":"Transició: restabliment de la Generalitat (1977) i Estatut de 1979","blocks":[{"text":"A la Diada de l''11 de setembre de 1977, més d''un milió de persones van reclamar pacíficament l''Estatut d''autonomia pels carrers de Barcelona. Poc després, el decret de 29 de setembre de 1977 va reconèixer Josep Tarradellas com a president de la Generalitat. Tarradellas va ser l''única autoritat republicana que va tornar d''un exili de quaranta anys per assumir un càrrec rellevant en la democràcia naixent.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"En ocasió de la Diada nacional de l''11 de setembre d''aquell any, més d''un milió de persones reclamava pacíficament pels carrers de Barcelona l''Estatut d''Autonomia, i poc després, el decret de 29 de setembre de 1977 reconeixia com a president de la Generalitat Josep Tarradellas, l''única autoritat republicana que retornà d''un exili de quaranta anys"}]},{"text":"L''Estatut de 1979 el va redactar la Comissió dels Vint, que es va reunir al parador de Sau. El text va ser assumit per l''Assemblea de Parlamentaris el 16 de desembre de 1978, aprovat per la comissió constitucional del Congrés el 13 d''agost de 1979 i sotmès a referèndum el 25 d''octubre de 1979, amb resultat favorable. El rei Joan Carles I el va sancionar el 18 de desembre de 1979.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Aquesta, denominada Comissió dels Vint es reuní al parador de Sau i produí un text que, assumit per l''Assemblea de Parlamentaris el 16 de desembre de 1978, va ser objecte de discussió a la comissió constitucional del Congrés dels Diputats, que l''aprovà el 13 d''agost de 1979, i fou sotmès a referèndum el 25 d''octubre del mateix any, amb resultat favorable. El 18 de desembre de 1979 l''Estatut d''Autonomia de Catalunya era sancionat pel rei Joan Carles I."}]},{"text":"Les primeres eleccions autonòmiques es van celebrar el 20 de març de 1980. El Parlament es va constituir el 10 d''abril i va elegir Heribert Barrera com a president de la cambra. Jordi Pujol, líder de la força més votada, va ser elegit 126è president de la Generalitat.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Les primeres eleccions autonòmiques, celebrades el 20 de març de 1980, van donar com a resultat un Parlament que es constituí el 10 d''abril i elegí com a president Heribert Barrera. Jordi Pujol, líder de la força política més votada, va ser elegit 126è president de la Generalitat."}]}]},{"n":"11","title":"L''Estatut de 2006 i l''etapa recent","blocks":[{"text":"El Pacte del Tinell, anomenat així perquè es va signar al saló noble de l''antic Palau Reial de Barcelona, va ser un acord entre tres forces que va permetre que la presidència recaigués en el candidat socialista Pasqual Maragall, alcalde de Barcelona del 1982 al 1997. En aquesta etapa es va reformar l''Estatut: el text final es va aprovar en el referèndum del 18 de juny de 2006 i va entrar en vigor el 9 d''agost del mateix any.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"L''acord entre les tres forces es coneix com a Pacte del Tinell perquè es va rubricar al saló noble de l''antic Palau Reial de Barcelona. Aquell pacte va fer possible que la Presidència de la Generalitat recaigués en el candidat socialista, Pasqual Maragall, que havia estat alcalde de Barcelona del 1982 al 1997."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"El text final resultant fou aprovat pel poble de Catalunya en el referèndum celebrat el 18 de juny de 2006 i va entrar en vigor el 9 d''agost del mateix any."}]},{"text":"L''11 de setembre de 2012, 1,5 milions de persones es van manifestar perquè Catalunya esdevingués un nou estat d''Europa. Carles Puigdemont va ser investit 130è president amb 70 vots a favor, 63 en contra i 2 abstencions de la CUP. Després d''un referèndum sobre la independència declarat il·legal pel Tribunal Constitucional, el Govern espanyol va aplicar l''article 155 de la Constitució i va suspendre l''autonomia de Catalunya el 27 d''octubre de 2017.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"L’11 de setembre de 2012, 1,5 milions de persones es van manifestar a favor que Catalunya esdevingués un nou Estat d’Europa."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Puigdemont va ser investit 130è president de la Generalitat amb 70 vots a favor, 63 en contra i 2 abstencions de la CUP."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Després de la celebració d’un referèndum sobre la independència, declarat il·legal pel Tribunal Constitucional, el Govern espanyol va aplicar l’article 155 de la Constitució i va suspendre l’autonomia de Catalunya el 27 d’octubre de 2017."}]},{"text":"Salvador Illa va ser investit 133è president de la Generalitat el 8 d''agost de 2024, en una cerimònia solemne al Saló Sant Jordi del Palau de la Generalitat (dada vigent a la font consultada el 6 de novembre de 2026). Les fonts oficials carregades no donen la llista completa de presidents entre Pujol (126è) i Illa (133è), de manera que no l''incloem aquí.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Salvador Illa va ser investit 133è president de la Generalitat el 8 d’agost de 2024, en una cerimònia solemne al Saló Sant Jordi del Palau de la Generalitat"}]}]},{"n":"12","title":"Símbols nacionals de Catalunya (art. 8 EAC)","blocks":[{"text":"L''article 8 de l''Estatut estableix que Catalunya, definida com a nacionalitat a l''article 1, té tres símbols nacionals: la bandera, la festa i l''himne. La bandera és la tradicional de quatre barres vermelles sobre fons groc, i ha de ser present als edificis públics i als actes oficials que se celebrin a Catalunya. La festa és l''Onze de Setembre i l''himne és «Els segadors».","refs":[{"ref":"Art. 8.1 i 8.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Cataluña, definida como nacionalidad en el artículo primero, tiene como símbolos nacionales la bandera, la fiesta y el himno. […] La bandera de Cataluña es la tradicional de cuatro barras rojas en fondo amarillo y debe estar presente en los edificios públicos y en los actos oficiales que tengan lugar en Cataluña."},{"ref":"Art. 8.3 i 8.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La fiesta de Cataluña es el Día Once de Septiembre. […] El himno de Cataluña es «Els segadors»."}]},{"text":"El Parlament ha de regular les diferents expressions del marc simbòlic i fixar-ne l''ordre protocol·lari, i la protecció jurídica dels símbols de Catalunya és la mateixa que la dels altres símbols de l''Estat.","refs":[{"ref":"Art. 8.5 i 8.6 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El Parlamento debe regular las distintas expresiones del marco simbólico de Cataluña y debe fijar su orden protocolario. […] La protección jurídica de los símbolos de Cataluña es la que corresponde a los demás símbolos del Estado."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"1283, Cort de Barcelona, Pere el Gran: neix el pactisme; el rei no pot fer constitucions ni cobrar impostos generals sense els tres braços (militar, eclesiàstic i reial o popular).","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"el sobirà no podia promulgar constitucions ni exigir impostos generals sense l’autorització dels tres estaments o braços"}]},{"text":"1410: mor Martí l''Humà sense descendència, Interregne; s''hi integra la Val d''Aran. 1412: Compromís de Casp.","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"que va acabar amb el Compromís de Casp de 1412."}]},{"text":"1455: insaculació (noms en un sac i sorteig). 1481: Constitució de l''Observança, amb Ferran II.","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"establint la Constitució de l’Observança"}]},{"text":"1640: pacte de Ceret amb França (7 de setembre). 1659: Tractat dels Pirineus (Rosselló, Conflent, Vallespir i part de la Cerdanya a França).","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"La Diputació va signar el pacte de Ceret amb França el 7 de setembre de 1640"}]},{"text":"11 de setembre de 1714: assalt final a Barcelona; Cardona, darrer reducte. 16 de gener de 1716: Nova Planta de Felip V.","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"El darrer reducte de resistència, Cardona, va caure pocs dies després."}]},{"text":"Mancomunitat: 1914-1925, primera experiència d''autogovern del segle XX.","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"la primera experiència d''autogovern català, la Mancomunitat de 1914-1925."}]},{"text":"1931: Generalitat provisional presidida per Macià; 20 de novembre de 1932: únic Parlament elegit en l''etapa republicana.","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"que fou elegit per primera i única vegada dins l''etapa republicana el 20 de novembre de 1932."}]},{"text":"Companys, afusellat al castell de Montjuïc el 15 d''octubre de 1940.","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"afusellat al castell de Montjuïc el dia 15 d''octubre de 1940."}]},{"text":"1977: Tarradellas reconegut president en tornar de l''exili; 1979: Estatut redactat per la Comissió dels Vint al parador de Sau; 2006: nou Estatut (referèndum del 18 de juny).","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Aquesta, denominada Comissió dels Vint es reuní al parador de Sau"}]},{"text":"Símbols (art. 8 EAC): bandera de quatre barres, festa de l''Onze de Setembre i himne «Els segadors». Illa és el 133è president (investit el 8 d''agost de 2024).","refs":[{"ref":"Art. 8.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El himno de Cataluña es «Els segadors»."}]}]}]'::jsonb, (select id from public.sources where url = 'https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat'), 'https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat', null, null, null, 'Otras normas citadas: EAC (https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087)'
  from public.topics t where t.slug = 'cultcat-01-historia-catalunya'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
