insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Espanya contemporània: dictadures, República i Transició"},{"n":"2","title":"Història universal: Revolució Francesa, Segona Guerra Mundial i ONU"},{"n":"3","title":"Integració europea: CECA, Tractat de Roma i ampliacions"},{"n":"4","title":"Món antic i medieval: Roma a Hispània, Xina, remences"},{"n":"5","title":"Fets del segle XX i XXI"}]'::jsonb, '["ONU, fundació un.org: «The United Nations is an international organization founded in 1945.»","Carta de les Nacions Unides, signatura un.org: «It was signed on 26 June 1945, in San Francisco, at the conclusion of the United Nations Conference on International Organization, and came into force on 24 October 1945.»","Constitució espanyola, referèndum Generalitat, Història de la Generalitat: «configuraren unes cambres que tingueren com a missió principal la redacció d''una constitució, que ser aprovada en referèndum el 6 de desembre de 1978.»","Fi de la dictadura franquista Generalitat, Història de la Generalitat: «encetaren un període de privació de la democràcia i els drets nacionals catalans que havia de durar fins a la mort del dictador el 20 de novembre de 1975.»","Transició, Adolfo Suárez Generalitat, Història de la Generalitat: «El 3 de juliol de 1976, fou nomenat president del govern Adolfo Suárez, que avançà de manera cada vegada més decidida cap a la reforma.»","Eleccions generals de 1977 Generalitat, Història de la Generalitat: «les primeres eleccions legislatives espanyoles democràtiques des de 1936, celebrades el 15 de juny de 1977»","Dictadura de Primo de Rivera Generalitat, Història de la Generalitat: «la del general Primo de Rivera (1923-1930) i la del general Franco (1939-1975).»","Segona República, 1931 Generalitat, Història de la Generalitat: «proclamà de manera unilateral «la República catalana com a Estat de la Federació Ibèrica» el dia 14, poques hores abans que a Madrid es procedís a proclamar la Segona República espanyola.»","OTAN, 1949 european-union.europa.eu: «4 de abril de 1949 — Creación de la OTAN Se crea la Organización del Tratado del Atlántico Norte (OTAN), una alianza intergubernamental de seguridad entre los Estados Unidos, Canadá y diez países de Europa Occidental.»","CECA, 1951 european-union.europa.eu: «La Comunidad Europea del Carbón y del Acero, fundada en 1951, fue el primer paso para garantizar una paz duradera.»","Tractat de Roma, 1957 european-union.europa.eu: «En 1957, el Tratado de Roma establece la Comunidad Económica Europea (CEE)»","Adhesió d''Espanya, 1986 european-union.europa.eu: «En 1981, Grecia pasa a ser el décimo miembro de las Comunidades Europeas, seguida cinco años más tarde por España y Portugal.»","Adhesió de Grècia, 1981 european-union.europa.eu: «En 1981, Grecia pasa a ser el décimo miembro de las Comunidades Europeas»","Atemptats de l''11 de setembre de 2001 european-union.europa.eu: «Varios aviones son secuestrados y estrellados contra las torres gemelas del World Trade Center, en Nueva York, y el Pentágono, en Washington. Mueren alrededor de 3 000 personas.»","Solidaritat, Gdańsk european-union.europa.eu: «Los trabajadores de los astilleros de la ciudad polaca de Gdansk, dirigidos por Lech Walesa, entran en huelga para reclamar más derechos.»","Auschwitz-Birkenau UNESCO, World Heritage List: «Auschwitz Birkenau German Nazi Concentration and Extermination Camp (1940-1945) (Date of Inscription: 1979).»","Declaració de Drets de l''Home i del Ciutadà, 1789 Conseil constitutionnel, DDHC 1789: «Déclaration des Droits de l''Homme et du Citoyen de 1789 […] Article 1er Les hommes naissent et demeurent libres et égaux en»","Mèrida, Augusta Emerita UNESCO, World Heritage List: «The colony of Augusta Emerita, which became present-day Mérida in Estremadura, was founded in 25 B.C. at the end of the Spanish Campaign and was the capital of Lusitania.»","Gran Muralla xinesa UNESCO, World Heritage List: «In c. 220 B.C., under Qin Shi Huang, sections of earlier fortifications were joined together to form a united defence system against invasions from the north.»","Remença DIEC2: «remença 2 f. [HIH] Dret que el senyor podia exigir del vassall subjecte a adscripció a la terra quan aquest volia abandonar-la.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Espanya al segle XX: les dues dictadures i la Segona República","blocks":[{"text":"Al segle XX Espanya va viure dues dictadures militars: la del general Primo de Rivera, entre 1923 i 1930, i la del general Franco, entre 1939 i 1975. Totes dues van coincidir amb una forta tendència centralitzadora. Per a l''examen, cal tenir clars els dos intervals de dates i no confondre''ls.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"especialment remarcada a les dues dictadures: la del general Primo de Rivera (1923-1930) i la del general Franco (1939-1975)."}]},{"text":"Entre totes dues hi ha la Segona República. Les eleccions municipals del 12 d''abril de 1931 van determinar la caiguda de la monarquia. El dia 14, a Barcelona, Francesc Macià va proclamar «la República catalana com a Estat de la Federació Ibèrica», i poques hores després es va proclamar a Madrid la Segona República espanyola. Fixa''t que el canvi de règim no va venir d''unes eleccions generals, sinó d''unes municipals.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Arran de les eleccions municipals de 12 d''abril de 1931, que determinaren la caiguda de la monarquia, Francesc Macià, líder d''Esquerra Republicana de Catalunya -partit triomfador a Catalunya- proclamà de manera unilateral «la República catalana com a Estat de la Federació Ibèrica» el dia 14, poques hores abans que a Madrid es procedís a proclamar la Segona República espanyola."}]},{"text":"La Guerra Civil va acabar amb la República. El 5 d''abril de 1938, quan ja es veia el desenllaç de la guerra, Franco va signar a Burgos un decret que abolia la Generalitat de Catalunya. Va començar un llarg període sense democràcia que va durar fins a la mort del dictador, el 20 de novembre de 1975: aquest és el fet que posa fi a la dictadura franquista.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"El dia 5 d''abril de 1938, a la vista ja del desenllaç de la guerra civil, el general Franco signà a Burgos un decret que abolia la Generalitat de Catalunya"},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"encetaren un període de privació de la democràcia i els drets nacionals catalans que havia de durar fins a la mort del dictador el 20 de novembre de 1975."}]}]},{"n":"2","title":"La Transició i la Constitució de 1978","blocks":[{"text":"Després de la mort de Franco va començar la Transició. El 3 de juliol de 1976 Adolfo Suárez va ser nomenat president del Govern i va avançar de manera cada vegada més decidida cap a la reforma política. Un cop legalitzats els partits polítics, el 15 de juny de 1977 es van celebrar les primeres eleccions legislatives democràtiques des de 1936.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"El 3 de juliol de 1976, fou nomenat president del govern Adolfo Suárez, que avançà de manera cada vegada més decidida cap a la reforma."},{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"Un cop legalitzats els partits polítics, les primeres eleccions legislatives espanyoles democràtiques des de 1936, celebrades el 15 de juny de 1977"}]},{"text":"Les Corts elegides el 1977 van tenir com a missió principal redactar una constitució, que es va aprovar en referèndum el 6 de desembre de 1978. La Constitució defineix Espanya com un estat social i democràtic de dret, amb quatre valors superiors: la llibertat, la justícia, la igualtat i el pluralisme polític; i fixa com a forma política la monarquia parlamentària.","refs":[{"ref":"Història de la Generalitat (Generalitat contemporània)","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"configuraren unes cambres que tingueren com a missió principal la redacció d''una constitució, que ser aprovada en referèndum el 6 de desembre de 1978."},{"ref":"Art. 1.1 i 1.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"España se constituye en un Estado social y democrático de Derecho, que propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político. […] La forma política del Estado español es la Monarquía parlamentaria."}]}]},{"n":"3","title":"Història universal: la Revolució Francesa i la Declaració de 1789","blocks":[{"text":"La Declaració dels Drets de l''Home i del Ciutadà de 1789 és un dels textos fundacionals dels drets moderns. La van aprovar els representants del poble francès constituïts en Assemblea Nacional, convençuts que la ignorància, l''oblit o el menyspreu dels drets de l''home eren les úniques causes de les desgràcies públiques i de la corrupció dels governs. El seu article 1 comença afirmant que els homes neixen i romanen lliures i iguals en drets.","refs":[{"ref":"Déclaration des Droits de l''Homme et du Citoyen","law":"Conseil constitutionnel, DDHC 1789","url":"https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/declaration-des-droits-de-l-homme-et-du-citoyen-de-1789","quote":"Les représentants du peuple français, constitués en Assemblée nationale, considérant que l''ignorance, l''oubli ou le mépris des droits de l''homme sont les seules causes des malheurs publics et de la corruption des gouvernements"},{"ref":"Déclaration de 1789, art. 1","law":"Conseil constitutionnel, DDHC 1789","url":"https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/declaration-des-droits-de-l-homme-et-du-citoyen-de-1789","quote":"Article 1er Les hommes naissent et demeurent libres et égaux en"}]},{"text":"Per situar l''Antic Règim que la Revolució va enderrocar, és útil recordar Versalles: segons la UNESCO, el palau de Versalles va ser la residència principal dels reis de França des de Lluís XIV fins a Lluís XVI. Les fonts oficials carregades no detallen altres episodis de la Revolució (presa de la Bastilla, etc.), de manera que no els desenvolupem aquí.","refs":[{"ref":"Palace and Park of Versailles (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"The Palace of Versailles was the principal residence of the French kings from the time of Louis XIV to Louis XVI."}]}]},{"n":"4","title":"La Segona Guerra Mundial i l''Holocaust","blocks":[{"text":"La Segona Guerra Mundial va acabar a Europa el 8 de maig de 1945. Un dels testimonis més durs del conflicte és Auschwitz-Birkenau, el camp de concentració i extermini nazi alemany (1940-1945), el més gran del Tercer Reich. La UNESCO el va inscriure a la Llista del patrimoni mundial el 1979. Segons les investigacions històriques que recull la UNESCO, hi van ser sistemàticament afamegades, torturades i assassinades 1,5 milions de persones, entre les quals un gran nombre de jueus.","refs":[{"ref":"Historia de la UE (1945-59)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"8 de mayo de 1945 – Fin de la Segunda Guerra Mundial en Europa"},{"ref":"Auschwitz Birkenau (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Auschwitz Birkenau German Nazi Concentration and Extermination Camp (1940-1945) (Date of Inscription: 1979)."},{"ref":"Auschwitz Birkenau (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"the largest in the Third Reich. According to historical investigations, 1.5 million people, among them a great number of Jews, were systematically starved, tortured and murdered in this camp"}]}]},{"n":"5","title":"L''Organització de les Nacions Unides (1945)","blocks":[{"text":"L''ONU és una organització internacional fundada el 1945. El seu document fundacional és la Carta de les Nacions Unides, signada el 26 de juny de 1945 a San Francisco, al final de la Conferència de les Nacions Unides sobre Organització Internacional, i que va entrar en vigor el 24 d''octubre de 1945. Compte amb la confusió: signatura a San Francisco el juny, entrada en vigor l''octubre.","refs":[{"ref":"ONU, About us","law":"un.org","url":"https://www.un.org/en/about-us","quote":"The United Nations is an international organization founded in 1945."},{"ref":"ONU, UN Charter","law":"un.org","url":"https://www.un.org/en/about-us","quote":"It was signed on 26 June 1945, in San Francisco, at the conclusion of the United Nations Conference on International Organization, and came into force on 24 October 1945."}]},{"text":"L''ONU va néixer amb 51 estats membres i actualment en té 193. Els seus òrgans principals són l''Assemblea General, el Consell de Seguretat, el Consell Econòmic i Social, el Consell d''Administració Fiduciària, la Cort Internacional de Justícia i la Secretaria. L''Assemblea General es reuneix cada any al setembre a Nova York.","refs":[{"ref":"ONU, About us","law":"un.org","url":"https://www.un.org/en/about-us","quote":"The UN’s Membership has grown from the original 51 Member States in 1945 to the current 193 Member States."},{"ref":"ONU, Main bodies","law":"un.org","url":"https://www.un.org/en/about-us","quote":"The main bodies of the United Nations are the General Assembly, the Security Council, the Economic and Social Council, the Trusteeship Council, the International Court of Justice, and the UN Secretariat."},{"ref":"ONU, Main bodies","law":"un.org","url":"https://www.un.org/en/about-us","quote":"Each year, in September, the full UN membership meets in the General Assembly Hall in New York for the annual General Assembly session"}]}]},{"n":"6","title":"La postguerra a Europa: OTAN, Consell d''Europa i CECA","blocks":[{"text":"Després de la guerra, el 4 d''abril de 1949 es va crear l''Organització del Tractat de l''Atlàntic Nord (OTAN), una aliança intergovernamental de seguretat entre els Estats Units, el Canadà i deu països de l''Europa occidental. El mateix 1949 es va fundar el Consell d''Europa, una organització internacional diferent de la Unió Europea que promou la democràcia, els drets humans i l''estat de dret.","refs":[{"ref":"Historia de la UE (1945-59)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"4 de abril de 1949 — Creación de la OTAN Se crea la Organización del Tratado del Atlántico Norte (OTAN), una alianza intergubernamental de seguridad entre los Estados Unidos, Canadá y diez países de Europa Occidental."},{"ref":"Presidència irlandesa del Consell de la UE","law":"Consell de la UE, presidència irlandesa 2026","url":"https://irish-presidency.consilium.europa.eu/en/presidency/presidency-of-the-council-of-the-eu/","quote":"The Council of Europe is not an EU institution. It is a separate international organisation, founded in 1949, that promotes democracy, human rights, and the rule of law across its 46 member countries."}]},{"text":"La integració europea va començar amb la Comunitat Europea del Carbó i de l''Acer (CECA), fundada el 1951 i considerada el primer pas per garantir una pau duradora. El 1957 el Tractat de Roma va establir la Comunitat Econòmica Europea (CEE) i va obrir una etapa de cooperació cada vegada més estreta. Ordre que cal recordar: CECA (1951) i després CEE pel Tractat de Roma (1957).","refs":[{"ref":"Historia de la UE (1945-59)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"La Comunidad Europea del Carbón y del Acero, fundada en 1951, fue el primer paso para garantizar una paz duradera. En 1957, el Tratado de Roma establece la Comunidad Económica Europea (CEE) y una nueva era de cooperación cada vez más estrecha en Europa."}]}]},{"n":"7","title":"Les ampliacions i la construcció de la Unió Europea","blocks":[{"text":"Els anys d''entrada dels estats a la UE són 1958, 1973, 1981, 1986, 1995, 2004, 2007 i 2013. Als anys setanta hi van entrar els primers nous membres: Dinamarca, Irlanda i el Regne Unit. El 1981 Grècia es va convertir en el desè membre de les Comunitats Europees, i cinc anys més tard, és a dir, el 1986, hi van entrar Espanya i Portugal.","refs":[{"ref":"Países de la UE","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Países por año de entrada 1958 1973 1981 1986 1995 2004 2007 2013"},{"ref":"Historia de la UE (1970-79)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Adhesión de los primeros nuevos miembros: Dinamarca, Irlanda y el Reino Unido"},{"ref":"Historia de la UE (1980-89)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"En 1981, Grecia pasa a ser el décimo miembro de las Comunidades Europeas, seguida cinco años más tarde por España y Portugal."}]},{"text":"El Tractat de Maastricht, signat el 7 de febrer de 1992 als Països Baixos, va entrar en vigor l''1 de novembre de 1993 i va crear oficialment la «Unió Europea». El 1993 també es va posar en marxa el mercat únic amb les quatre llibertats: lliure circulació de persones, mercaderies, serveis i capitals. El 1995 hi van entrar Àustria, Finlàndia i Suècia, i un petit poble de Luxemburg va donar nom a l''Acord de Schengen.","refs":[{"ref":"Historia de la UE (1990-99)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"7 de febrero de 1992 – Tratado de Maastricht En Maastricht (Países Bajos) se firma el Tratado de la Unión Europea."},{"ref":"Historia de la UE (1990-99)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"El tratado, que entra en vigor el 1 de noviembre de 1993, crea oficialmente la «Unión Europea»."},{"ref":"Historia de la UE (1990-99)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"En 1993, el mercado único se puso en marcha con las «cuatro libertades»: libre circulación de personas, mercancías, servicios y capital."},{"ref":"Historia de la UE (1990-99)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Austria, Finlandia y Suecia se adhieren a la UE en 1995, y un pequeño pueblo de Luxemburgo da su nombre al Acuerdo de Schengen"}]},{"text":"Entre 2000 i 2009 la UE es va ampliar amb dotze nous països i es va signar el Tractat de Lisboa. L''1 de gener de 2002 van començar a circular els bitllets i les monedes d''euro en dotze països. L''1 de juliol de 2013 Croàcia es va convertir en el 28è estat membre, i el 2016 el Regne Unit va votar en referèndum a favor de sortir de la UE.","refs":[{"ref":"Historia de la UE (2000-09)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Cómo evolucionó la Unión Europea de 2000 a 2009, con la adhesión de 12 nuevos países, el euro como moneda de curso legal y la firma del Tratado de Lisboa."},{"ref":"Historia de la UE (2000-09)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"1 de enero de 2002 – Empiezan a circular los billetes y monedas en euros en doce países de la UE"},{"ref":"Historia de la UE (2010-19)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"1 de julio de 2013 – Croacia se convierte en el 28.º Estado miembro de la UE"},{"ref":"Historia de la UE (2010-19)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Pero en un referéndum celebrado en 2016, el Reino Unido vota a favor de abandonar la UE."}]},{"text":"La UE té símbols propis: des de 1985 el seu himne oficial és l''«Himne a l''alegria» de Beethoven, sense lletra, i des de l''any 2000 el seu lema és «Unida en la diversitat». El 10 de desembre de 2012 la UE va rebre el Premi Nobel de la Pau en una cerimònia a Oslo.","refs":[{"ref":"Símbolos de la UE","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"El «Himno a la alegría», sin letra, de Beethoven se convirtió en el himno oficial de la UE en 1985."},{"ref":"Símbolos de la UE","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"En el año 2000, «Unida en la diversidad» fue adoptado como lema de la Unión Europea."},{"ref":"Historia de la UE (2010-19)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"10 de diciembre de 2012 – La UE recibe el Premio Nobel de la Paz La Unión Europea recibe el Premio Nobel de la Paz en una ceremonia celebrada en Oslo."}]}]},{"n":"8","title":"Món antic: Roma a Hispània","blocks":[{"text":"La romanització va deixar a la península Ibèrica grans conjunts que avui són patrimoni mundial. La colònia d''Augusta Emerita, l''actual Mèrida (Extremadura), es va fundar el 25 aC, al final de les campanyes d''Hispània, i va ser la capital de la Lusitània. Tarraco, l''actual Tarragona, va ser una gran ciutat administrativa i mercantil de la Hispània romana i el centre del culte imperial de totes les províncies ibèriques.","refs":[{"ref":"Archaeological Ensemble of Mérida (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"The colony of Augusta Emerita, which became present-day Mérida in Estremadura, was founded in 25 B.C. at the end of the Spanish Campaign and was the capital of Lusitania."},{"ref":"Archaeological Ensemble of Tarraco (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Tarraco (modern-day Tarragona) was a major administrative and mercantile city in Roman Spain and the centre of the Imperial cult for all the Iberian provinces."}]},{"text":"Una altra gran obra romana és l''aqüeducte de Segòvia, construït probablement cap a l''any 50 dC i molt ben conservat, amb dos nivells d''arcs. Recorda la diferència entre aC (abans de Crist, com Mèrida) i dC (després de Crist, com l''aqüeducte).","refs":[{"ref":"Old Town of Segovia and its Aqueduct (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"The Roman aqueduct of Segovia, probably built c. A.D. 50, is remarkably well preserved. This impressive construction, with its two tiers of arches"}]}]},{"n":"9","title":"Món antic i medieval fora d''Europa: la Gran Muralla xinesa","blocks":[{"text":"Cap al 220 aC, sota l''emperador Qin Shi Huang, es van unir trams de fortificacions anteriors per formar un sistema de defensa unificat contra les invasions del nord. La construcció va continuar fins a la dinastia Ming (1368-1644), quan la Gran Muralla es va convertir en l''estructura militar més gran del món.","refs":[{"ref":"The Great Wall (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"In c. 220 B.C., under Qin Shi Huang, sections of earlier fortifications were joined together to form a united defence system against invasions from the north. Construction continued up to the Ming dynasty (1368–1644), when the Great Wall became the world''s largest military structure."}]}]},{"n":"10","title":"Edat mitjana: feudalisme i remences","blocks":[{"text":"El feudalisme va ser el sistema que va configurar l''estructura juridicopública i economicosocial de la major part de l''Europa occidental durant l''edat mitjana, i en alguns aspectes es va allargar fins a l''edat moderna. Dins d''aquest sistema, a Catalunya, la remença era el dret que el senyor podia exigir al vassall lligat a la terra quan aquest la volia abandonar; és a dir, el pagès havia de pagar per marxar. Per extensió, «remença» designa també el pagès sotmès a aquest dret (pagès de remença).","refs":[{"ref":"DIEC, feudalisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"feudalisme m. [HIH] [LC] Sistema que configurà l’estructura juridicopública i economicosocial de la major part dels països de l’Occident europeu durant els segles medievals i que en alguns aspectes s’ha prolongat fins a l’edat moderna."},{"ref":"DIEC, remença","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"remença 2 f. [HIH] Dret que el senyor podia exigir del vassall subjecte a adscripció a la terra quan aquest volia abandonar-la. 3 m. Pagès de remença."}]},{"text":"L''edat mitjana va acabar donant pas al Renaixement, el moviment cultural que, a partir del segle XIV a Itàlia i després arreu d''Europa, va impulsar la recuperació de les idees i l''art de l''antiguitat grecoromana. Les fonts oficials carregades no expliquen la guerra remença ni la Sentència de Guadalupe; si surten a examen, caldria una font oficial addicional.","refs":[{"ref":"DIEC, renaixement","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"renaixement 2 2 m. [HIH] [LC] Moviment cultural impulsat, a partir del segle xiv a Itàlia i després arreu d’Europa, per a la recuperació de les idees i l’art antic grecoromà."}]}]},{"n":"11","title":"Fets del segle XX i XXI: fi de la Guerra Freda i 11-S","blocks":[{"text":"Als anys vuitanta, els treballadors de les drassanes de la ciutat polonesa de Gdańsk, dirigits per Lech Wałęsa, van fer vaga per reclamar més drets. Al final d''aquella dècada van caure els règims comunistes de l''Europa central i oriental. Un altre concepte de segle XX que pot sortir és l''apartheid, el sistema oficial de segregació racial de les poblacions no blanques vigent a Sud-àfrica fins al 1991.","refs":[{"ref":"Historia de la UE (1980-89)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Los trabajadores de los astilleros de la ciudad polaca de Gdansk, dirigidos por Lech Walesa, entran en huelga para reclamar más derechos."},{"ref":"Historia de la UE (1980-89)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Al final de la década se derrumban los regímenes comunistas de Europa Central y del Este."},{"ref":"DIEC, apartheid","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"apartheid m. [LC] [PO] Sistema oficial de segregació racial de les poblacions no blanques vigent a Sud-àfrica fins a l’any 1991."}]},{"text":"L''11 de setembre de 2001 diversos avions van ser segrestats i estavellats contra les Torres Bessones del World Trade Center, a Nova York, i contra el Pentàgon, a Washington. Hi van morir unes 3.000 persones.","refs":[{"ref":"Historia de la UE (2000-09)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Varios aviones son secuestrados y estrellados contra las torres gemelas del World Trade Center, en Nueva York, y el Pentágono, en Washington. Mueren alrededor de 3 000 personas."}]},{"text":"Pel que fa a l''actualitat internacional, la UE assenyala que la dècada de 2010 va estar marcada per la resposta a la crisi financera, l''adhesió de Croàcia i el vot del Regne Unit per sortir de la UE. Les fonts carregades estan llegides el 6 de novembre de 2026; els fets posteriors no hi són.","refs":[{"ref":"Historia de la UE (2010-19)","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Cómo evolucionó la Unión Europea de 2010 a 2019, con la respuesta a la crisis financiera, la adhesión de Croacia a la UE y el voto del Reino Unido para abandonar la UE."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Dictadures: Primo de Rivera (1923-1930) i Franco (1939-1975). La de Franco acaba amb la mort del dictador el 20 de novembre de 1975.","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"la del general Primo de Rivera (1923-1930) i la del general Franco (1939-1975)."}]},{"text":"14 d''abril de 1931: proclamació de la Segona República espanyola, després de les municipals del 12 d''abril.","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"poques hores abans que a Madrid es procedís a proclamar la Segona República espanyola."}]},{"text":"Transició: Suárez (3 de juliol de 1976), primeres eleccions (15 de juny de 1977), Constitució aprovada en referèndum (6 de desembre de 1978).","refs":[{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"celebrades el 15 de juny de 1977"}]},{"text":"1789: Declaració dels Drets de l''Home i del Ciutadà; article 1, els homes neixen i romanen lliures i iguals en drets.","refs":[{"ref":"DDHC 1789","law":"Conseil constitutionnel, DDHC 1789","url":"https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/declaration-des-droits-de-l-homme-et-du-citoyen-de-1789","quote":"Déclaration des Droits de l''Homme et du Citoyen de 1789"}]},{"text":"ONU: fundada el 1945; Carta signada a San Francisco el 26 de juny de 1945; 193 estats membres.","refs":[{"ref":"ONU","law":"un.org","url":"https://www.un.org/en/about-us","quote":"Currently made up of 193 Member States"}]},{"text":"OTAN: 4 d''abril de 1949. CECA: 1951. Tractat de Roma (CEE): 1957.","refs":[{"ref":"Historia de la UE","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"La Comunidad Europea del Carbón y del Acero, fundada en 1951"}]},{"text":"Grècia, desè membre el 1981; Espanya i Portugal, el 1986; Croàcia, el 28è el 2013.","refs":[{"ref":"Historia de la UE","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"En 1981, Grecia pasa a ser el décimo miembro de las Comunidades Europeas"}]},{"text":"Auschwitz-Birkenau: el camp més gran del Tercer Reich, patrimoni mundial des de 1979.","refs":[{"ref":"Auschwitz Birkenau (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Date of Inscription: 1979"}]},{"text":"Augusta Emerita (Mèrida), fundada el 25 aC, capital de la Lusitània; Gran Muralla unificada sota Qin Shi Huang (cap al 220 aC).","refs":[{"ref":"The Great Wall (UNESCO)","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"In c. 220 B.C., under Qin Shi Huang"}]},{"text":"Remença: dret del senyor a cobrar al pagès adscrit a la terra que la volia abandonar. Gdańsk: vaga dirigida per Lech Wałęsa.","refs":[{"ref":"DIEC, remença","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Dret que el senyor podia exigir del vassall subjecte a adscripció a la terra quan aquest volia abandonar-la."}]}]}]'::jsonb, (select id from public.sources where url = 'https://european-union.europa.eu/index_es'), 'https://european-union.europa.eu/index_es', null, null, null, 'Otras normas citadas: un.org (https://www.un.org/en/about-us), Generalitat, Història de la Generalitat (https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat), UNESCO, World Heritage List (https://whc.unesco.org/en/list/), Conseil constitutionnel, DDHC 1789 (https://www.conseil-constitutionnel.fr/le-bloc-de-constitutionnalite/declaration-des-droits-de-l-homme-et-du-citoyen-de-1789), DIEC2 (https://dlc.iec.cat/)'
  from public.topics t where t.slug = 'cultcat-02-historia-espanya-mon'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Anuari estadístic de Catalunya i El municipi en xifres (Institut d''Estadística de Catalunya)', 'https://www.idescat.cat/indicadors/?id=aec&lang=ca', 'web_oficial'::public.source_kind, 'Institut d''Estadística de Catalunya (Idescat)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('cultcat-03-geografia', 'Cultura general 3. Geografia de Catalunya, d''Espanya i del món') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local', 'guardia-urbana-barcelona') and t.slug = 'cultcat-03-geografia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Relleu i rius de Catalunya (Idescat)"},{"n":"2","title":"Organització territorial: municipis i comarques"},{"n":"3","title":"Població de Catalunya i Barcelona"},{"n":"4","title":"Capitals i dades d''Europa"},{"n":"5","title":"Conceptes de geografia física i cartografia"}]'::jsonb, '["Cim més alt de Catalunya Idescat: «Pica d''Estats 3.143 Pallars Sobirà/França»","Capital de Portugal european-union.europa.eu, fitxes de país: «[Portugal] Capital: Lisboa»","Vallès Occidental, capital Idescat: «Vallès Occidental Sabadell i Terrassa Barcelona 23 970.228 Vallès Oriental Granollers»","Equador DIEC2: «equador 2 m. [FIA] [GG] [LC] Cercle màxim de l’esfera terrestre tots els punts del qual equidisten dels dos pols.»","Primer meridià DIEC2: «primer meridià Meridià que passa per l’observatori anglès de Greenwich, adoptat actualment com a origen de les longituds geogràfiques»","Delta DIEC2: «delta 1 m. [GG] [GL] [LC] Formació sedimentària dipositada per un riu en el desguàs a la mar o en un llac»","Nombre de municipis de Catalunya Idescat: «Catalunya 947 8.124.126»","Rius de les conques internes Idescat: «Muga 65 854 Castelló d''Empúries 51,9 Fluvià 97 1.125 Esponellà 144,5 Ter 208 3.010 Masies de Roda 403,0 […] Llobregat 170 4.948»","Pedraforca Idescat: «Pedraforca 2.506 Berguedà»","Turó de l''Home Idescat: «Prelitoral Turó de l''Home 1.706 Montseny Vallès Oriental»","Aran, capital Idescat: «Aran Vielha e Mijaran Lleida 9 10.651»","Comarca del Lluçanès Idescat: «Llei 7/2023, de creació de la comarca del Lluçanès, que també modifica territorialment Osona»","Països Baixos, capital european-union.europa.eu, fitxes de país: «[Países Bajos] Capital: Ámsterdam. El Parlamento y el Gobierno tienen su sede en La Haya»","Latitud DIEC2: «latitud 2 1 f. [GG] Distància d’un lloc a l’equador mesurada per l’arc de meridià que va des del dit lloc a l’equador.»","Estuari DIEC2: «estuari m. [GG] [LC] Embocadura àmplia d’un riu afectada per les marees.»","Superfície d''Espanya european-union.europa.eu, fitxes de país: «Extensión geográfica: 505 983 km2»","Població de Catalunya, 2026 Idescat: «2026 (p) 6.017.087 839.692 464.600 889.331 8.210.710 49.570.725 16,6»","Barcelonès, municipis Idescat: «Barcelonès Barcelona Barcelona 5 2.398.280»","Alta Ribagorça, capital Idescat: «Alta Ribagorça Pont de Suert, el Lleida 3 4.051»","Barcelona, superfície i població Idescat: «Barcelona Codi 080193 Comarca Barcelonès Població (2025) 1.713.247 Superfície (km²) 101,35 Densitat (hab./km²) 16.904,3»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Relleu de Catalunya: els cims principals","blocks":[{"text":"L''Anuari estadístic de Catalunya d''Idescat recull, en una taula d''orografia amb dades del 2018, els cims principals del país agrupats per sistemes muntanyencs. El sostre de Catalunya és la Pica d''Estats, de 3.143 metres, als Pirineus, en el límit entre el Pallars Sobirà i França. També als Pirineus, el Puigmal arriba als 2.909 metres i fa de frontera entre el Ripollès i França. Per tant, si una pregunta demana el cim més alt, la resposta és la Pica d''Estats, i no el Puigmal, que és més baix.","refs":[{"ref":"Anuari estadístic, taula 15185","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Orografia. Sistemes muntanyencs. Cims principals Catalunya. 2018 Cims Altitud (m) Serra/massís Comarca/país Pirineus Pica d''Estats 3.143 Pallars Sobirà/França Puigmal 2.909 Ripollès/França"}]},{"text":"Dins de Catalunya hi ha altres cims emblemàtics que convé situar en la seva comarca. El Pedraforca, de 2.506 metres, és al Berguedà. A la Serralada Prelitoral, el cim de referència és el Turó de l''Home, de 1.706 metres, que pertany al massís del Montseny i és al Vallès Oriental. Un truc per recordar l''ordre d''altituds: Pica d''Estats (més de 3.000 m), Puigmal (gairebé 2.900 m), Pedraforca (uns 2.500 m) i Turó de l''Home (uns 1.700 m).","refs":[{"ref":"Anuari estadístic, taula 15185","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Pedraforca 2.506 Berguedà Prelitoral Turó de l''Home 1.706 Montseny Vallès Oriental"}]},{"text":"Les fonts oficials carregades no detallen altres serralades o massissos (com la Serralada Litoral o la Depressió Central), de manera que aquests apunts es limiten als quatre cims de la taula d''Idescat.","refs":[{"ref":"Anuari estadístic, taula 15185","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Cims principals Catalunya. 2018"}]}]},{"n":"2","title":"Rius de les conques internes","blocks":[{"text":"Idescat publica també les dades dels sistemes fluvials de les conques internes de Catalunya (dades del 2025): per a cada riu, la longitud en quilòmetres, l''extensió de la conca en quilòmetres quadrats i l''aportació anual mesurada en una estació d''aforament. La Muga fa 65 km, amb una conca de 854 km², i es mesura a Castelló d''Empúries. El Fluvià fa 97 km i té una conca de 1.125 km², amb l''estació a Esponellà.","refs":[{"ref":"Anuari estadístic, taula 15188","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Sistemes fluvials. Conques internes. Aportació anual Catalunya. 2025 Rius i afluents Longitud (km) Extensió conca (km²) Estació d''aforament Valor Muga 65 854 Castelló d''Empúries 51,9 Fluvià 97 1.125 Esponellà 144,5"}]},{"text":"Els dos rius més importants de les conques internes són el Ter i el Llobregat. El Ter és el més llarg dels quatre, amb 208 km, i una conca de 3.010 km²; la seva aportació mesurada a Masies de Roda és de 403,0 hm³ l''any. El Llobregat és més curt (170 km), però té una conca més gran (4.948 km²), i es mesura a Castellbell i el Vilar (381,6 hm³/any). Cal no confondre, doncs, «el riu més llarg» (Ter) amb «la conca més extensa» (Llobregat).","refs":[{"ref":"Anuari estadístic, taula 15188","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Ter 208 3.010 Masies de Roda 403,0 Llobregat 170 4.948 Castellbell i el Vilar 381,6"}]},{"text":"La mateixa taula defineix dos conceptes bàsics. L''aportació d''un riu és el volum total d''aigua que passa en un any pel punt on se''n mesura el cabal, i s''expressa en hectòmetres cúbics per any. La conca hidrogràfica és el conjunt de vessants inclinats cap a un mateix curs d''aigua: és a dir, tot el territori que hi aboca l''aigua.","refs":[{"ref":"Anuari estadístic, taula 15188","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Aportació d''un riu Volum total d''aigua que passa en un any (hm³/any) pel punt on se''n mesura el cabal. Conca hidrogràfica Conjunt de vessants inclinats cap a un mateix curs d''aigua."}]}]},{"n":"3","title":"Organització territorial: municipis, vegueries i comarques","blocks":[{"text":"L''Estatut d''autonomia estableix que Catalunya estructura la seva organització territorial bàsica en municipis i vegueries, i que l''àmbit supramunicipal el formen, en tot cas, les comarques, regulades per una llei del Parlament (art. 83 EAC). Els altres ens supramunicipals que creï la Generalitat es basen en la voluntat de col·laboració i associació dels municipis.","refs":[{"ref":"Art. 83 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Cataluña estructura su organización territorial básica en municipios y veguerías. 2. El ámbito supramunicipal está constituido, en todo caso, por las comarcas, que debe regular una ley del Parlamento."}]},{"text":"El municipi és l''ens local bàsic de l''organització territorial i el mitjà essencial de participació de la comunitat local en els afers públics; el governa l''Ajuntament, format per l''alcalde o alcaldessa i els regidors (art. 86 EAC). La vegueria és l''àmbit territorial per al govern intermunicipal de cooperació local, té personalitat jurídica pròpia i és també la divisió que fa servir la Generalitat per organitzar els seus serveis (art. 90 EAC).","refs":[{"ref":"Art. 86 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El municipio es el ente local básico de la organización territorial de Cataluña y el medio esencial de participación de la comunidad local en los asuntos públicos."},{"ref":"Art. 90 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La veguería es el ámbito territorial específico para el ejercicio del gobierno intermunicipal de cooperación local"}]},{"text":"La comarca és un ens local amb personalitat jurídica pròpia format per municipis per gestionar competències i serveis locals. La seva creació, modificació i supressió es regulen per llei del Parlament (art. 92 EAC). Per això, la comarca més recent, el Lluçanès, es va crear per una llei, la Llei 7/2023, que també va modificar el territori d''Osona.","refs":[{"ref":"Art. 92 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La comarca se configura como ente local con personalidad jurídica propia y está formada por municipios para la gestión de competencias y servicios locales. 2. La creación, modificación y supresión de las comarcas, así como el establecimiento del régimen jurídico de estos entes, se regulan por una ley del Parlamento."}]}]},{"n":"4","title":"Comarques i capitals","blocks":[{"text":"Segons l''Anuari d''Idescat (municipis i població a 1 de gener de 2025), Catalunya té 947 municipis i 8.124.126 habitants, repartits entre les comarques i l''Aran. Des del maig de 2023 les dades es presenten segons la nova distribució territorial derivada de la Llei 7/2023, de creació de la comarca del Lluçanès, que també modifica territorialment Osona.","refs":[{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Catalunya 947 8.124.126 A partir del maig de 2023, les dades es presenten segons la distribució territorial vigent (Llei 7/2023, de creació de la comarca del Lluçanès, que també modifica territorialment Osona)."}]},{"text":"La taula indica la capital de cada comarca, la província o províncies a què pertanyen els municipis, el nombre de municipis i la població. El Lluçanès té per capital Prats de Lluçanès i 8 municipis. Osona, amb capital a Vic, té 42 municipis repartits entre les províncies de Barcelona i Girona. El Moianès té capital a Moià i 10 municipis. El Bages té capital a Manresa; el Maresme, a Mataró; la Garrotxa, a Olot; l''Alt Empordà, a Figueres, i l''Alt Camp, a Valls.","refs":[{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Lluçanès Prats de Lluçanès Barcelona 8 5.723 Maresme Mataró Barcelona 30 477.375 Moianès Moià Barcelona 10 14.864"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Osona Vic Barcelona/Girona (3) 42 165.946"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Alt Camp Valls Tarragona 23 47.138 Alt Empordà Figueres Girona 68 150.044"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Bages Manresa Barcelona 30 187.620"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Garrotxa Olot Girona 21 63.339"}]},{"text":"Hi ha casos que surten sovint a examen. El Vallès Occidental té una capitalitat compartida entre Sabadell i Terrassa (23 municipis i 970.228 habitants), mentre que el Vallès Oriental té per capital Granollers. El Barcelonès, amb capital a Barcelona, té només 5 municipis però 2.398.280 habitants: és la comarca més poblada de la taula. L''Alta Ribagorça, on hi ha la Vall de Boí, té capital al Pont de Suert i només 3 municipis.","refs":[{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Vallès Occidental Sabadell i Terrassa Barcelona 23 970.228 Vallès Oriental Granollers"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Barcelonès Barcelona Barcelona 5 2.398.280"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Alta Ribagorça Pont de Suert, el Lleida 3 4.051"}]},{"text":"Altres capitals de comarca de la taula: el Pallars Sobirà té capital a Sort i el Pallars Jussà, a Tremp; el Segrià, a Lleida; la Noguera, a Balaguer; l''Urgell, a Tàrrega; el Baix Camp, a Reus; el Baix Ebre, a Tortosa; el Montsià, a Amposta; el Priorat, a Falset, i la Terra Alta, a Gandesa.","refs":[{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Pallars Jussà Tremp Lleida 14 13.593 Pallars Sobirà Sort Lleida 15 7.332"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Segrià Lleida Lleida 38 221.630"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Montsià Amposta Tarragona 12 72.825 Noguera Balaguer Lleida 30 39.957"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Terra Alta Gandesa Tarragona 12 11.385 Urgell Tàrrega Lleida 20 39.294"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Baix Camp Reus Tarragona 28 207.529 Baix Ebre Tortosa Tarragona 14 84.077"},{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Priorat Falset Tarragona 23 9.415"}]}]},{"n":"5","title":"L''Aran, entitat territorial singular","blocks":[{"text":"L''Aran figura a la taula d''Idescat al costat de les comarques: té per capital Vielha e Mijaran, 9 municipis i 10.651 habitants (2025). No s''ha de confondre amb Sort, que és la capital del Pallars Sobirà, ni amb el Pont de Suert, capital de l''Alta Ribagorça.","refs":[{"ref":"Anuari estadístic, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Aran Vielha e Mijaran Lleida 9 10.651"}]},{"text":"L''Estatut reconeix l''Aran com una realitat occitana amb identitat cultural, històrica, geogràfica i lingüística, i com a entitat territorial singular dins de Catalunya. La llengua occitana, anomenada aranès a l''Aran, n''és la llengua pròpia i és oficial a Catalunya. La seva institució de govern és el Conselh Generau, i el síndic n''és la màxima representació (art. 94 EAC). Històricament, la Val d''Aran es va integrar voluntàriament al Principat el 1410.","refs":[{"ref":"Art. 6.5 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La lengua occitana, denominada aranés en Arán, es la lengua propia de este territorio y es oficial en Cataluña"},{"ref":"Art. 94.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La institución de Gobierno de Arán es el Conselh Generau, que está formado por el Síndic, el Plen des Conselhèrs e Conselhères Generaus y la Comission d''Auditors de Compdes."},{"ref":"Història de la Generalitat","law":"Generalitat, Història de la Generalitat","url":"https://web.gencat.cat/ca/generalitat/qui-som/historia-generalitat","quote":"la integració voluntària de la Val d’Aran (un territori de senyoria reial autònom) al Principat el 1410"}]}]},{"n":"6","title":"Població de Catalunya","blocks":[{"text":"Segons les dades provisionals d''Idescat a 1 de gener de 2026, Catalunya té 8.210.710 habitants, que són el 16,6% dels 49.570.725 habitants d''Espanya. Per províncies, Barcelona en té 6.017.087; Tarragona, 889.331; Girona, 839.692, i Lleida, 464.600. Un càlcul senzill mostra el pes de la província de Barcelona: 6.017.087 / 8.210.710 ≈ 0,73, és a dir, prop de tres de cada quatre catalans hi viuen.","refs":[{"ref":"Anuari estadístic, taula 15223","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Població a 1 de gener. Províncies Barcelona Girona Lleida Tarragona Catalunya Espanya % Cat./Esp. 2026 (p) 6.017.087 839.692 464.600 889.331 8.210.710 49.570.725 16,6"}]},{"text":"Un any abans, a 1 de gener de 2025, Catalunya tenia 8.124.126 habitants, el 16,5% dels 49.128.297 d''Espanya; per tant, la població ha crescut en 86.584 persones en un any. La portada del web d''Idescat, consultada el 6 de novembre de 2026, mostra ja una xifra més actualitzada de 8.237.683 habitants: les xifres de població canvien cada any i convé recordar la data de cada dada.","refs":[{"ref":"Anuari estadístic, taula 15223","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"2025 5.959.941 830.429 458.226 875.530 8.124.126 49.128.297 16,5"},{"ref":"Portada idescat.cat, 06/11/2026","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Estadística oficial de Catalunya 8.237.683 Població"}]}]},{"n":"7","title":"Barcelona: superfície i població","blocks":[{"text":"El municipi de Barcelona (codi 080193, comarca del Barcelonès) té, segons El municipi en xifres d''Idescat, 1.713.247 habitants (2025) en una superfície de 101,35 km², amb una densitat de 16.904,3 habitants per km² i una altitud de 13 metres. La densitat és simplement la població dividida per la superfície: 1.713.247 / 101,35 ≈ 16.904. La ciutat concentra més de dues terceres parts de la població del Barcelonès (1.713.247 de 2.398.280).","refs":[{"ref":"El municipi en xifres","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Barcelona Codi 080193 Comarca Barcelonès Població (2025) 1.713.247 Superfície (km²) 101,35 Densitat (hab./km²) 16.904,3 Altitud (m) 13"}]},{"text":"El padró municipal de l''Ajuntament dona per al 2026 una població de 1.729.963 persones, una lleugera disminució però el segon valor més alt dels darrers quaranta anys. La xifra és diferent de la d''Idescat perquè prové d''una altra font i d''un altre any. La ciutat té deu districtes, i l''edat mitjana de la població és de 44,6 anys.","refs":[{"ref":"Informe del padró 2026","law":"Ajuntament de Barcelona, padró 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"La població de Barcelona disminueix lleugerament el 2026 i se situa en 1.729.963 persones, el segon valor més elevat dels darrers quaranta anys."},{"ref":"Informe del padró 2026","law":"Ajuntament de Barcelona, padró 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"A set dels deu districtes es redueix lleugerament el nombre de residents"},{"ref":"Informe del padró 2026","law":"Ajuntament de Barcelona, padró 2026","url":"https://dades.ajuntament.barcelona.cat/informe-padro-poblacio/ca/seccio_2.html","quote":"L’edat mitjana de la població repunta lleugerament fins al 44,6 anys."}]}]},{"n":"8","title":"Capitals dels estats de la Unió Europea","blocks":[{"text":"Les fitxes de país del portal oficial de la UE indiquen la capital de cada estat membre. Algunes de les que surten a examen: la capital de Portugal és Lisboa; la d''Espanya, Madrid; la de França, París; la d''Alemanya, Berlín; la d''Itàlia, Roma; la de Grècia, Atenes, i la d''Irlanda, Dublín.","refs":[{"ref":"Fitxa de Portugal","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"[Portugal] Capital: Lisboa"},{"ref":"Fitxa d''Espanya","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"[España] Capital: Madrid"},{"ref":"Fitxes de França, Alemanya, Itàlia, Grècia i Irlanda","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"[Francia] Capital: París […] [Alemania] Capital: Berlín […] [Italia] Capital: Roma […] [Grecia] Capital: Atenas […] [Irlanda] Capital: Dublín"}]},{"text":"El cas dels Països Baixos és especial: la capital és Amsterdam, però el Parlament i el Govern tenen la seu a la Haia. Per tant, la resposta correcta a «quina és la capital» és Amsterdam, encara que la Haia sigui la seu de les institucions.","refs":[{"ref":"Fitxa dels Països Baixos","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"[Países Bajos] Capital: Ámsterdam. El Parlamento y el Gobierno tienen su sede en La Haya"}]},{"text":"Altres capitals de la UE: Eslovàquia, Bratislava; Xipre, Nicòsia; Suècia, Estocolm; Bulgària, Sofia; Polònia, Varsòvia, i Croàcia, Zagreb.","refs":[{"ref":"Fitxes de diversos estats","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"[Eslovaquia] Capital: Bratislava […] [Chipre] Capital: Nicosia […] [Suecia] Capital: Estocolmo […] [Bulgaria] Capital: Sofía […] [Polonia] Capital: Varsovia […] [Croacia] Capital: Zagreb"}]}]},{"n":"9","title":"Dades d''Europa: superfícies, població i moneda","blocks":[{"text":"La fitxa oficial de la UE dona a Espanya una extensió geogràfica de 505.983 km², és a dir, uns 506.000 km². França és més extensa, amb 638.475 km², i té 69.112.309 habitants; Alemanya té 83.467.117 habitants. Si comparem superfícies, França és aproximadament una quarta part més gran que Espanya (638.475 / 505.983 ≈ 1,26).","refs":[{"ref":"Fitxa d''Espanya","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"Extensión geográfica: 505 983 km2"},{"ref":"Fitxa de França","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"Superficie: 638 475 km2 Población: 69 112 309"},{"ref":"Fitxa d''Alemanya","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"[Alemania] Capital: Berlín Población: 83 467 117"}]},{"text":"La UE té 27 estats membres, i l''euro és la moneda oficial de 21 d''aquests països, que formen la zona euro (dada consultada el novembre del 2026). Bulgària n''és membre des de l''1 de gener de 2026. Suècia manté la corona sueca, tot i que s''ha compromès a adoptar l''euro quan compleixi les condicions, i Polònia, amb l''esloti, es prepara per adoptar-lo.","refs":[{"ref":"Portal de la UE","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Hoy en día, el euro (€) es la moneda oficial de 21 de los 27 países de la UE, que juntos constituyen la eurozona, denominada oficialmente zona del euro."},{"ref":"Fitxa de Bulgària","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"Zona del euro: Miembro desde el 1 de enero de 2026"},{"ref":"Fitxes de Suècia i Polònia","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"Moneda: corona sueca (SEK). Suecia se ha comprometido a adoptar el euro cuando reúna las condiciones necesarias. […] Moneda: esloti (PLN). Polonia se prepara en la actualidad para adoptar el euro."}]}]},{"n":"10","title":"Conceptes de cartografia: equador, paral·lels, latitud i meridià","blocks":[{"text":"L''equador és el cercle màxim de l''esfera terrestre tots els punts del qual són a la mateixa distància dels dos pols. Els paral·lels terrestres són cercles menors determinats per plans paral·lels a l''equador que tallen l''esfera terrestre. L''equador, per tant, és el paral·lel més gran i el que serveix de referència.","refs":[{"ref":"DIEC, equador","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"equador 2 m. [FIA] [GG] [LC] Cercle màxim de l’esfera terrestre tots els punts del qual equidisten dels dos pols."},{"ref":"DIEC, paral·lel","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"paral·lel terrestre Cercle menor de l’esfera terrestre determinat per la intersecció d’un pla paral·lel a l’equador amb l’esfera terrestre."}]},{"text":"La latitud d''un lloc és la seva distància a l''equador, mesurada per l''arc de meridià que va des del lloc fins a l''equador. No s''ha de confondre amb l''altitud (l''altura sobre el nivell del mar) ni amb la longitud, que es compta a partir del primer meridià. El primer meridià és el que passa per l''observatori anglès de Greenwich, adoptat com a origen de les longituds geogràfiques: és el de 0° 0′ 0″ de longitud.","refs":[{"ref":"DIEC, latitud","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"latitud 2 1 f. [GG] Distància d’un lloc a l’equador mesurada per l’arc de meridià que va des del dit lloc a l’equador."},{"ref":"DIEC, primer meridià","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"primer meridià Meridià que passa per l’observatori anglès de Greenwich, adoptat actualment com a origen de les longituds geogràfiques, o sigui, el de 00° 00′ 00″ de longitud."}]}]},{"n":"11","title":"Conceptes de geografia física: desembocadures i formes del relleu","blocks":[{"text":"Un riu pot acabar de dues maneres que convé distingir. El delta és una formació sedimentària que el riu diposita on desguassa, a la mar o en un llac. L''estuari, en canvi, és una embocadura àmplia d''un riu afectada per les marees: no hi ha acumulació de sediments, sinó una boca oberta on entra la marea.","refs":[{"ref":"DIEC, delta","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"delta 1 m. [GG] [GL] [LC] Formació sedimentària dipositada per un riu en el desguàs a la mar o en un llac"},{"ref":"DIEC, estuari","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"estuari m. [GG] [LC] Embocadura àmplia d’un riu afectada per les marees."}]},{"text":"Altres termes útils: un meandre és una volta sinuosa que fa un curs d''aigua; l''erosió és el conjunt de processos de despreniment i transport de materials pels agents en moviment, que contribueixen a formar el relleu; i una glacera és una massa de glaç continental formada per la compactació de la neu en una regió de neus perpètues, que es mou lentament per gravetat.","refs":[{"ref":"DIEC, meandre","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"meandre 1 m. [GL] [LC] Volta sinuosa que fa un curs d’aigua, un riu, un camí."},{"ref":"DIEC, erosió","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Conjunt de processos de despreniment i transport dels detritus pels agents en moviment que operen sobre la superfície del sòl, que concorren a la formació del relleu."},{"ref":"DIEC, glacera","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"glacera f. [GG] [GL] [LC] Massa de glaç continental formada per compactació i recristal·lització de la neu en una regió de neus perpètues, que es mou lentament per gravetat rost avall"}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"El cim més alt de Catalunya és la Pica d''Estats (3.143 m), entre el Pallars Sobirà i França.","refs":[{"ref":"Idescat, taula 15185","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Pica d''Estats 3.143 Pallars Sobirà/França"}]},{"text":"El Pedraforca (2.506 m) és al Berguedà, i el Turó de l''Home (1.706 m), al Montseny.","refs":[{"ref":"Idescat, taula 15185","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Pedraforca 2.506 Berguedà Prelitoral Turó de l''Home 1.706 Montseny Vallès Oriental"}]},{"text":"El Ter (208 km) és el riu més llarg de les conques internes; el Llobregat (170 km) té la conca més gran.","refs":[{"ref":"Idescat, taula 15188","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Ter 208 3.010 Masies de Roda 403,0 Llobregat 170 4.948"}]},{"text":"Catalunya té 947 municipis (2025); el Barcelonès en té 5, l''Alta Ribagorça 3 i l''Aran 9.","refs":[{"ref":"Idescat, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Catalunya 947 8.124.126"}]},{"text":"El Vallès Occidental té capitalitat compartida (Sabadell i Terrassa); l''Aran, Vielha e Mijaran; l''Alta Ribagorça, el Pont de Suert.","refs":[{"ref":"Idescat, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Vallès Occidental Sabadell i Terrassa Barcelona 23 970.228"}]},{"text":"La comarca més recent és el Lluçanès, creada per la Llei 7/2023.","refs":[{"ref":"Idescat, taula 15902","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Llei 7/2023, de creació de la comarca del Lluçanès"}]},{"text":"A 1 de gener de 2026 (provisional), Catalunya té 8.210.710 habitants, el 16,6% de la població d''Espanya.","refs":[{"ref":"Idescat, taula 15223","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"2026 (p) 6.017.087 839.692 464.600 889.331 8.210.710 49.570.725 16,6"}]},{"text":"Barcelona fa 101,35 km² i tenia 1.713.247 habitants el 2025 (Idescat).","refs":[{"ref":"El municipi en xifres","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Població (2025) 1.713.247 Superfície (km²) 101,35"}]},{"text":"La capital dels Països Baixos és Amsterdam (el Parlament i el Govern són a la Haia); Espanya fa uns 506.000 km².","refs":[{"ref":"Fitxa de la UE","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"[Países Bajos] Capital: Ámsterdam. El Parlamento y el Gobierno tienen su sede en La Haya"}]},{"text":"El primer meridià passa per Greenwich; la latitud es mesura des de l''equador.","refs":[{"ref":"DIEC","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"primer meridià Meridià que passa per l’observatori anglès de Greenwich"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.idescat.cat/indicadors/?id=aec&lang=ca'), 'https://www.idescat.cat/indicadors/?id=aec&lang=ca', null, null, null, 'Otras normas citadas: european-union.europa.eu, fitxes de país (https://european-union.europa.eu/principles-countries-history/eu-countries_es), DIEC2 (https://dlc.iec.cat/)'
  from public.topics t where t.slug = 'cultcat-03-geografia'
