insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Estils artístics: romànic, gòtic, barroc i avantguardes"},{"n":"2","title":"Elements arquitectònics de les esglésies"},{"n":"3","title":"Modernisme i Gaudí"},{"n":"4","title":"Patrimoni mundial a Catalunya i Espanya"},{"n":"5","title":"Patrimoni mundial universal i el Guernica"}]'::jsonb, '["Guernica, autor Museo Reina Sofía, Guernica: «GUERNICA Picasso, Pablo (Pablo Ruiz Picasso)»","Romànic DIEC2: «romànic 2 1 adj. [AR] Relatiu o pertanyent a l’art, a l’estil arquitectònic, desenvolupat en diversos països de l’Europa occidental entre el preromànic i el gòtic.»","Gaudí i el modernisme Ajuntament de Barcelona, Any Gaudí: «Antoni Gaudí i Cornet, nascut el 1852, és una de les figures cabdals de l’arquitectura universal i el màxim exponent del modernisme català.»","Retaule DIEC2: «retaule 1 m. [AR] [LC] Obra d’arquitectura, amb escultures, pintures, que compon la decoració d’un altar.»","Rosassa DIEC2: «rosassa f. [AQ] [AR] [LC] Gran finestral circular, calat i vidrat, que es troba als murs de les esglésies gòtiques, especialment a la façana.»","Machu Picchu UNESCO, World Heritage List: «It was probably the most amazing urban creation of the Inca Empire at its height»","Palau de la Música i Sant Pau UNESCO, World Heritage List: «Palau de la Música Catalana and Hospital de Sant Pau, Barcelona (Date of Inscription: 1997). These are two of the finest contributions to Barcelona''s architecture by the Catalan art nouveau architect Lluís Domènech i Montaner.»","Monestir de Poblet UNESCO, World Heritage List: «This Cistercian abbey in Catalonia is one of the largest in Spain. At its centre is a 12th-century church. The austere, majestic monastery, which has a fortified royal residence and contains the pantheon of the kings of Catalonia and Aragon»","Absis DIEC2: «absis 1 m. [AQ] [AR] [LC] Part d’una església, comunament de planta semicircular, que sobresurt de la façana posterior i que conté un altar.»","Guernica, encàrrec Museo Reina Sofía, Guernica: «el lienzo Guernica nació para formar parte del Pabellón Español en la Exposición Internacional de París, de 1937.»","Impressionisme DIEC2: «impressionisme m. [AR] [LC] Corrent estètic, especialment pictòric, iniciat i desenvolupat sobretot a França, que se centra en el paisatge o en els temes quotidians i cerca de donar la impressió immediata produïda a l’artista per la vista dels objectes.»","Cubisme DIEC2: «cubisme m. [AR] [LC] Moviment artístic que considera el volum com l’atribut important dels objectes i tracta d’expressar-lo plàsticament per mitjà tan sols de figures i sòlids geomètrics.»","Taj Mahal UNESCO, World Heritage List: «An immense mausoleum of white marble, built in Agra between 1631 and 1648 by order of the Mughal emperor Shah Jahan in memory of his favourite wife»","Petra UNESCO, World Heritage List: «Inhabited since prehistoric times, this Nabataean caravan-city, situated between the Red Sea and the Dead Sea»","Llotja de la Seda de València UNESCO, World Heritage List: «It is a masterpiece of late Gothic architecture.»","Guernica, retorn a Espanya Museo Reina Sofía, Guernica: «regresando la obra finalmente a nuestro país en el año 1981.»","Surrealisme DIEC2: «surrealisme m. [AR] [FLL] [FS] Moviment literari, artístic i filosòfic, sorgit a França l’any 1924»","Acròpoli d''Atenes UNESCO, World Heritage List: «an exceptional group of artists put into effect the ambitious plans of Athenian statesman Pericles and, under the inspired guidance of the sculptor Pheidias»","Obres de Gaudí, patrimoni mundial UNESCO, World Heritage List: «The seven buildings are: Parque Güell; Palacio Güell; Casa Mila; Casa Vicens; Gaudí’s work on the Nativity façade and Crypt of La Sagrada Familia; Casa Batlló Crypt in Colonia Güell.»","Barroc DIEC2: «barroc 1 1 adj. [AQ] [AR] [LC] Relatiu o pertanyent a un estil artístic, evolució complexa del Renaixement, aparegut a Itàlia a les darreries del segle xvi i predominant a Europa fins gran part del segle xviii.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Romànic i gòtic","blocks":[{"text":"El romànic és l''art i l''estil arquitectònic que es va desenvolupar en diversos països de l''Europa occidental entre el preromànic i el gòtic. És, doncs, anterior al gòtic. A Catalunya en tenim un conjunt excepcional a la Vall de Boí, una vall estreta de l''Alta Ribagorça, als Pirineus, on cada poble té una església romànica envoltada de camps tancats; la UNESCO la va inscriure a la Llista del patrimoni mundial el 2000.","refs":[{"ref":"DIEC, romànic","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"romànic 2 1 adj. [AR] Relatiu o pertanyent a l’art, a l’estil arquitectònic, desenvolupat en diversos països de l’Europa occidental entre el preromànic i el gòtic."},{"ref":"UNESCO, fitxa 988","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Catalan Romanesque Churches of the Vall de Boí (Date of Inscription: 2000). The narrow Vall de Boí is situated in the high Pyrénées, in the Alta Ribagorça region and is surrounded by steep mountains. Each village in the valley contains a Romanesque church"}]},{"text":"El gòtic és l''art i l''estil arquitectònic que es va estendre per Europa des del segle XII fins al Renaixement. Un bon exemple de gòtic tardà és la Llotja de la Seda de València, construïda entre el 1482 i el 1533 per al comerç de la seda, que la UNESCO qualifica d''obra mestra de l''arquitectura gòtica tardana.","refs":[{"ref":"DIEC, gòtic","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"gòtic 3 2 adj. [AQ] [AR] [LC] Relatiu o pertanyent a l’art, a l’estil arquitectònic, estès per Europa des del segle xii al Renaixement."},{"ref":"UNESCO, fitxa 782","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Built between 1482 and 1533, this group of buildings was originally used for trading in silk (hence its name, the Silk Exchange) and it has always been a centre for commerce. It is a masterpiece of late Gothic architecture."}]}]},{"n":"2","title":"Del Renaixement al barroc i al romanticisme","blocks":[{"text":"El Renaixement és el moviment cultural que, a partir del segle XIV a Itàlia i després arreu d''Europa, va voler recuperar les idees i l''art antic grecoromà. El barroc n''és una evolució complexa: va aparèixer a Itàlia a les darreries del segle XVI i va predominar a Europa fins a bona part del segle XVIII. Així, la seqüència és romànic, gòtic (des del segle XII), Renaixement (des del XIV a Itàlia) i barroc (finals del XVI - XVIII).","refs":[{"ref":"DIEC, renaixement","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"renaixement 2 2 m. [HIH] [LC] Moviment cultural impulsat, a partir del segle xiv a Itàlia i després arreu d’Europa, per a la recuperació de les idees i l’art antic grecoromà."},{"ref":"DIEC, barroc","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"barroc 1 1 adj. [AQ] [AR] [LC] Relatiu o pertanyent a un estil artístic, evolució complexa del Renaixement, aparegut a Itàlia a les darreries del segle xvi i predominant a Europa fins gran part del segle xviii."}]},{"text":"Al segle XIX, el romanticisme va ser un moviment artístic que defugia la formalitat restrictiva del classicisme, és a dir, l''aplicació rigorosa dels cànons artístics. Les fonts oficials carregades no detallen el neoclassicisme ni altres estils intermedis.","refs":[{"ref":"DIEC, romanticisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"romanticisme 2 m. [AR] [LC] Moviment artístic del segle xix que defuig la formalitat restrictiva del classicisme, l’aplicació rigorosa dels cànons artístics."}]}]},{"n":"3","title":"Els corrents moderns i les avantguardes","blocks":[{"text":"L''impressionisme és un corrent estètic, sobretot pictòric, iniciat i desenvolupat principalment a França. Se centra en el paisatge i en els temes quotidians, i busca transmetre la impressió immediata que produeixen en l''artista els objectes que veu. Per això les preguntes el relacionen amb la «impressió immediata».","refs":[{"ref":"DIEC, impressionisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"impressionisme m. [AR] [LC] Corrent estètic, especialment pictòric, iniciat i desenvolupat sobretot a França, que se centra en el paisatge o en els temes quotidians i cerca de donar la impressió immediata produïda a l’artista per la vista dels objectes."}]},{"text":"El cubisme és un moviment artístic que considera el volum l''atribut més important dels objectes i l''expressa només amb figures i sòlids geomètrics. El surrealisme és un moviment literari, artístic i filosòfic sorgit a França el 1924, que proclama l''automatisme psíquic, la ruptura de la sintaxi, l''associació violenta d''imatges incoherents i la importància del món oníric, de l''instint i de la revolta.","refs":[{"ref":"DIEC, cubisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"cubisme m. [AR] [LC] Moviment artístic que considera el volum com l’atribut important dels objectes i tracta d’expressar-lo plàsticament per mitjà tan sols de figures i sòlids geomètrics."},{"ref":"DIEC, surrealisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"surrealisme m. [AR] [FLL] [FS] Moviment literari, artístic i filosòfic, sorgit a França l’any 1924, que proclama l’automatisme psíquic, la ruptura de la sintaxi, la violenta associació d’imatges incoherents i la importància del món oníric, de l’instint i de la revolta."}]},{"text":"Una obra que combina aquests llenguatges és el Guernica de Picasso, que el Museo Reina Sofía defineix com un quadre complex, tardocubista i surrealista, però arrelat a la tradició pictòrica occidental. Les fonts carregades no donen noms d''altres artistes de les avantguardes.","refs":[{"ref":"Museo Reina Sofía","law":"Museo Reina Sofía, Guernica","url":"https://www.museoreinasofia.es/colecciones/obra/guernica","quote":"Guernica es un cuadro complejo, tardocubista y surrealista, pero que está imbricado en la tradición pictórica occidental."}]}]},{"n":"4","title":"Elements arquitectònics de les esglésies","blocks":[{"text":"L''absis és la part d''una església, normalment de planta semicircular, que sobresurt de la façana posterior i que conté un altar. A les esglésies romàniques, com les de la Vall de Boí, és un dels elements més característics de la capçalera.","refs":[{"ref":"DIEC, absis","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"absis 1 m. [AQ] [AR] [LC] Part d’una església, comunament de planta semicircular, que sobresurt de la façana posterior i que conté un altar."}]},{"text":"La rosassa és un gran finestral circular, calat i vidrat, propi dels murs de les esglésies gòtiques, sobretot de la façana. És un element que ajuda a distingir el gòtic del romànic en una pregunta d''identificació.","refs":[{"ref":"DIEC, rosassa","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"rosassa f. [AQ] [AR] [LC] Gran finestral circular, calat i vidrat, que es troba als murs de les esglésies gòtiques, especialment a la façana."}]},{"text":"El retaule és una obra d''arquitectura, amb escultures i pintures, que forma la decoració d''un altar. Per tant, l''absis és un espai de l''edifici, mentre que el retaule és una obra que decora l''altar i la rosassa és una finestra.","refs":[{"ref":"DIEC, retaule","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"retaule 1 m. [AR] [LC] Obra d’arquitectura, amb escultures, pintures, que compon la decoració d’un altar."}]}]},{"n":"5","title":"El modernisme","blocks":[{"text":"El modernisme és un moviment artístic, literari i arquitectònic que es va desenvolupar a finals del segle XIX i principis del XX a l''Europa occidental i als Estats Units, caracteritzat per la voluntat de modernitat. El diccionari de l''IEC n''esmenta com a figures representatives a Catalunya Antoni Gaudí i Lluís Domènech i Montaner.","refs":[{"ref":"DIEC, modernisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"modernisme 3 m. [AR] [FLL] Moviment artístic, literari i arquitectònic, que es desenvolupà al final del segle xix i al principi del segle xx a l’Europa occidental i als Estats Units, caracteritzat per la voluntat de modernitat. Antoni Gaudí i Lluís Domènech i Montaner són figures representatives del Modernisme a Catalunya."}]},{"text":"Lluís Domènech i Montaner és l''autor del Palau de la Música Catalana i de l''Hospital de Sant Pau, a Barcelona, que la UNESCO considera dues de les millors aportacions a l''arquitectura de la ciutat i que va inscriure com a patrimoni mundial el 1997. Atenció: aquests dos edificis no són de Gaudí.","refs":[{"ref":"UNESCO, fitxa 804","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Palau de la Música Catalana and Hospital de Sant Pau, Barcelona (Date of Inscription: 1997). These are two of the finest contributions to Barcelona''s architecture by the Catalan art nouveau architect Lluís Domènech i Montaner."}]}]},{"n":"6","title":"Antoni Gaudí i l''Any Gaudí 2026","blocks":[{"text":"Antoni Gaudí i Cornet (1852-1926) és, segons l''Ajuntament de Barcelona, una de les figures cabdals de l''arquitectura universal i el màxim exponent del modernisme català. El 7 de juny de 1926 va ser atropellat per un tramvia a la Gran Via de les Corts Catalanes i va morir el 10 de juny.","refs":[{"ref":"Ajuntament de Barcelona, 07/06/2026","law":"Ajuntament de Barcelona, Any Gaudí","url":"https://ajuntament.barcelona.cat/premsa/2026/06/07/barcelona-ret-homenatge-a-antoni-gaudi-amb-una-placa-en-el-mateix-punt-on-va-ser-atropellat-lany-1926/","quote":"Antoni Gaudí i Cornet, nascut el 1852, és una de les figures cabdals de l’arquitectura universal i el màxim exponent del modernisme català."},{"ref":"Ajuntament de Barcelona, 07/06/2026","law":"Ajuntament de Barcelona, Any Gaudí","url":"https://ajuntament.barcelona.cat/premsa/2026/06/07/barcelona-ret-homenatge-a-antoni-gaudi-amb-una-placa-en-el-mateix-punt-on-va-ser-atropellat-lany-1926/","quote":"on va ser atropellat per un tramvia el 7 de juny de 1926."},{"ref":"Ajuntament de Barcelona, 07/06/2026","law":"Ajuntament de Barcelona, Any Gaudí","url":"https://ajuntament.barcelona.cat/premsa/2026/06/07/barcelona-ret-homenatge-a-antoni-gaudi-amb-una-placa-en-el-mateix-punt-on-va-ser-atropellat-lany-1926/","quote":"la inauguració de la torre de Jesucrist de la Sagrada Família, prevista el 10 de juny, data de la mort de l’arquitecte."}]},{"text":"El 2026 se celebra l''Any Gaudí, que commemora el centenari de la seva mort. En aquest marc es va inaugurar la torre de Jesucrist de la Sagrada Família, coincidint amb la visita del papa Lleó XIV, que hi va celebrar una missa solemne. També es commemoren els cent anys del Park Güell com a parc públic, i Barcelona és el 2026 Capital Mundial de l''Arquitectura (dades de notícies municipals del 2026).","refs":[{"ref":"Ajuntament de Barcelona, 07/06/2026","law":"Ajuntament de Barcelona, Any Gaudí","url":"https://ajuntament.barcelona.cat/premsa/2026/06/07/barcelona-ret-homenatge-a-antoni-gaudi-amb-una-placa-en-el-mateix-punt-on-va-ser-atropellat-lany-1926/","quote":"Aquest acte s’inscriu en el marc de l’Any Gaudí, impulsat per les institucions per commemorar el centenari de la seva mort"},{"ref":"Ajuntament de Barcelona, 29/05/2026","law":"Ajuntament de Barcelona, visita de Lleó XIV","url":"https://ajuntament.barcelona.cat/oficina-afers-religiosos/ca/noticies/barcelona-acollira-aquest-juny-la-visita-del-papa-lleo-xiv-1640185","quote":"L’arribada del pontífex coincideix amb la commemoració dels cent anys de la mort d’Antoni Gaudí i tindrà com a moment central la celebració d’una missa solemne a la basílica de la Sagrada Família, així com la inauguració de la torre de Jesucrist"},{"ref":"Ajuntament de Barcelona, 05/11/2026","law":"Ajuntament de Barcelona, centenari del Park Güell","url":"https://ajuntament.barcelona.cat/premsa/2026/11/05/el-park-guell-presenta-una-exposicio-de-900-fotografies-que-recorren-un-segle-de-la-seva-historia/","quote":"la commemoració dels cent anys del Park Güell com a parc públic i coincideix amb l’Any Gaudí i la Capitalitat Mundial de l’Arquitectura Barcelona 2026."}]}]},{"n":"7","title":"Patrimoni mundial a Catalunya","blocks":[{"text":"Les obres d''Antoni Gaudí són patrimoni mundial des del 1984. La UNESCO hi inclou set edificis, a Barcelona o als voltants: el Park Güell, el Palau Güell, la Casa Milà, la Casa Vicens, la façana del Naixement i la cripta de la Sagrada Família, la Casa Batlló i la cripta de la Colònia Güell. Una pregunta típica és identificar quin edifici no hi és: per exemple, el Palau de la Música, que és de Domènech i Montaner.","refs":[{"ref":"UNESCO, fitxa 320","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Works of Antoni Gaudí (Date of Inscription: 1984). Seven properties built by the architect Antoni Gaudí (1852–1926) in or near Barcelona"},{"ref":"UNESCO, fitxa 320","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"The seven buildings are: Parque Güell; Palacio Güell; Casa Mila; Casa Vicens; Gaudí’s work on the Nativity façade and Crypt of La Sagrada Familia; Casa Batlló Crypt in Colonia Güell."}]},{"text":"El monestir de Poblet, inscrit el 1991, és una abadia cistercenca de Catalunya, una de les més grans d''Espanya. Al centre hi ha una església del segle XII, i el conjunt inclou una residència reial fortificada i el panteó dels reis de Catalunya i Aragó.","refs":[{"ref":"UNESCO, fitxa 518","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Poblet Monastery (Date of Inscription: 1991). This Cistercian abbey in Catalonia is one of the largest in Spain. At its centre is a 12th-century church. The austere, majestic monastery, which has a fortified royal residence and contains the pantheon of the kings of Catalonia and Aragon"}]},{"text":"També són patrimoni mundial a Catalunya les esglésies romàniques de la Vall de Boí (2000), el Palau de la Música Catalana i l''Hospital de Sant Pau (1997) i el conjunt arqueològic de Tàrraco (2000), l''actual Tarragona, que va ser una gran ciutat administrativa i comercial de la Hispània romana i el centre del culte imperial de totes les províncies ibèriques.","refs":[{"ref":"UNESCO, fitxa 875","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Archaeological Ensemble of Tarraco (Date of Inscription: 2000). Tarraco (modern-day Tarragona) was a major administrative and mercantile city in Roman Spain and the centre of the Imperial cult for all the Iberian provinces."}]}]},{"n":"8","title":"Patrimoni mundial a la resta d''Espanya","blocks":[{"text":"A la resta d''Espanya, la UNESCO protegeix, entre d''altres, l''Alhambra, el Generalife i l''Albaicín de Granada (els jardins del Generalife eren la residència rural dels emirs dels segles XIII i XIV); la cova d''Altamira, que representa l''apogeu de l''art rupestre paleolític, desenvolupat entre el 35.000 i l''11.000 aC, i el conjunt arqueològic de Mèrida, l''antiga Augusta Emerita, fundada el 25 aC i capital de la Lusitània.","refs":[{"ref":"UNESCO, fitxa 314","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"To the east of the Alhambra fortress and residence are the magnificent gardens of the Generalife, the former rural residence of the emirs who ruled this part of Spain in the 13th and 14th centuries."},{"ref":"UNESCO, fitxa 310","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Cave of Altamira and Paleolithic Cave Art of Northern Spain. The property represents the apogee of Paleolithic cave art that developed across Europe, from the Urals to the Iberian Peninusula, from 35,000 to 11,000 BC."},{"ref":"UNESCO, fitxa 664","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"The colony of Augusta Emerita, which became present-day Mérida in Estremadura, was founded in 25 B.C. at the end of the Spanish Campaign and was the capital of Lusitania."}]},{"text":"També hi figuren la ciutat vella de Segòvia i el seu aqüeducte romà, construït probablement cap a l''any 50 dC i amb dos pisos d''arcs; la ciutat històrica de Toledo, marcada per la convivència de les tres grans religions (judaisme, cristianisme i islam); la Llotja de la Seda de València, i el Paseo del Prado i el Buen Retiro de Madrid, amb les fonts d''Apol·lo, de Neptú i de Cibeles.","refs":[{"ref":"UNESCO, fitxa 311","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"The Roman aqueduct of Segovia, probably built c. A.D. 50, is remarkably well preserved. This impressive construction, with its two tiers of arches"},{"ref":"UNESCO, fitxa 379","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"the existence of three major religions – Judaism, Christianity and Islam – was a major factor."},{"ref":"UNESCO, fitxa 1618","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Paseo del Prado and Buen Retiro, a landscape of Arts and Sciences. The avenue features major fountains, notably the Fuente de Apolo and the Fuente de Neptuno, and the Fuente de Cibeles"}]}]},{"n":"9","title":"Patrimoni mundial universal: Europa","blocks":[{"text":"L''Acròpoli d''Atenes es va transformar en un monument únic gràcies a un grup excepcional d''artistes que van executar els plans de l''estadista atenenc Pèricles sota la direcció inspirada de l''escultor Fídies. Cal recordar la parella: Pèricles (el polític) i Fídies (l''escultor).","refs":[{"ref":"UNESCO, fitxa 404","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"an exceptional group of artists put into effect the ambitious plans of Athenian statesman Pericles and, under the inspired guidance of the sculptor Pheidias, transformed the rocky hill into a unique monument of thought and the art"}]},{"text":"A França, el palau i el parc de Versalles (1979) van ser la residència principal dels reis francesos des de Lluís XIV fins a Lluís XVI, i les ribes del Sena a París (1991) inclouen des del Louvre fins a la torre Eiffel, a més de les obres mestres de Notre-Dame i la Sainte-Chapelle. A Polònia, el camp d''Auschwitz-Birkenau (1979), el més gran del Tercer Reich, recorda el genocidi nazi: hi van ser assassinades sistemàticament 1,5 milions de persones, moltes d''elles jueves.","refs":[{"ref":"UNESCO, fitxa 83","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Palace and Park of Versailles (Date of Inscription: 1979). The Palace of Versailles was the principal residence of the French kings from the time of Louis XIV to Louis XVI."},{"ref":"UNESCO, fitxa 600","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"From the Louvre to the Eiffel Tower, from the Place de la Concorde to the Grand and Petit Palais, the evolution of Paris and its history can be seen from the River Seine. The Cathedral of Notre-Dame and the Sainte Chapelle are architectural masterpieces"},{"ref":"UNESCO, fitxa 31","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"the largest in the Third Reich. According to historical investigations, 1.5 million people, among them a great number of Jews, were systematically starved, tortured and murdered in this camp"}]}]},{"n":"10","title":"Patrimoni mundial universal: Amèrica, Àsia i Àfrica","blocks":[{"text":"Machu Picchu, al Perú, és a 2.430 metres sobre el nivell del mar, enmig d''un bosc tropical de muntanya, i va ser probablement la creació urbana més extraordinària de l''Imperi inca en el seu moment de màxim esplendor. Chichén Itzá, a la península del Yucatán (Mèxic), va ser un dels grans centres maies. L''Estàtua de la Llibertat, feta a París per l''escultor Bartholdi amb la col·laboració de Gustave Eiffel, va ser un regal de França pel centenari de la independència nord-americana i es va inaugurar el 1886.","refs":[{"ref":"UNESCO, fitxa 274","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Machu Picchu stands 2,430 m above sea-level, in the middle of a tropical mountain forest, in an extraordinarily beautiful setting. It was probably the most amazing urban creation of the Inca Empire at its height"},{"ref":"UNESCO, fitxa 483","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"This sacred site was one of the greatest Mayan centres of the Yucatán peninsula."},{"ref":"UNESCO, fitxa 307","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Made in Paris by the French sculptor Bartholdi, in collaboration with Gustave Eiffel (who was responsible for the steel framework), this towering monument to liberty was a gift from France on the centenary of American independence. Inaugurated in 1886"}]},{"text":"Petra, habitada des de la prehistòria, era una ciutat caravanera dels nabateus situada entre el mar Roig i el mar Mort, cruïlla entre Aràbia, Egipte i Síria-Fenícia. El Taj Mahal és un immens mausoleu de marbre blanc construït a Agra entre el 1631 i el 1648 per ordre de l''emperador mogol Shah Jahan en memòria de la seva esposa preferida, i és la joia de l''art musulmà a l''Índia.","refs":[{"ref":"UNESCO, fitxa 326","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Inhabited since prehistoric times, this Nabataean caravan-city, situated between the Red Sea and the Dead Sea, was an important crossroads between Arabia, Egypt and Syria-Phoenicia."},{"ref":"UNESCO, fitxa 252","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"An immense mausoleum of white marble, built in Agra between 1631 and 1648 by order of the Mughal emperor Shah Jahan in memory of his favourite wife, the Taj Mahal is the jewel of Muslim art in India"}]},{"text":"La Gran Muralla xinesa es va formar cap al 220 aC, sota Qin Shi Huang, unint fortificacions anteriors, i es va continuar construint fins a la dinastia Ming (1368-1644). Angkor (Cambodja) conserva les capitals de l''Imperi khmer dels segles IX al XV, amb el temple d''Angkor Wat. A Egipte, Memfis i la seva necròpolis, amb els camps de piràmides de Gizeh a Dahshur, eren considerades una de les set meravelles del món.","refs":[{"ref":"UNESCO, fitxa 438","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"In c. 220 B.C., under Qin Shi Huang, sections of earlier fortifications were joined together to form a united defence system against invasions from the north. Construction continued up to the Ming dynasty (1368–1644)"},{"ref":"UNESCO, fitxa 668","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Angkor Archaeological Park contains the magnificent remains of the different capitals of the Khmer Empire, from the 9th to the 15th century. They include the famous Temple of Angkor Wat"},{"ref":"UNESCO, fitxa 86","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"Memphis and its Necropolis – the Pyramid Fields from Giza to Dahshur. […] In ancient times, the site was considered one of the Seven Wonders of the World."}]}]},{"n":"11","title":"El Guernica de Picasso","blocks":[{"text":"El Guernica és un oli sobre tela de Pablo Ruiz Picasso, pintat a París entre l''1 de maig i el 4 de juny de 1937. Va néixer per formar part del Pavelló Espanyol de l''Exposició Internacional de París del 1937, i el que va impulsar Picasso a pintar-lo va ser la notícia del bombardeig de l''aviació alemanya sobre la vila basca que dona nom a l''obra.","refs":[{"ref":"Museo Reina Sofía","law":"Museo Reina Sofía, Guernica","url":"https://www.museoreinasofia.es/colecciones/obra/guernica","quote":"GUERNICA Picasso, Pablo (Pablo Ruiz Picasso) 1937 (1 de mayo-4 de junio, París) Óleo sobre lienzo"},{"ref":"Museo Reina Sofía","law":"Museo Reina Sofía, Guernica","url":"https://www.museoreinasofia.es/colecciones/obra/guernica","quote":"el lienzo Guernica nació para formar parte del Pabellón Español en la Exposición Internacional de París, de 1937."},{"ref":"Museo Reina Sofía","law":"Museo Reina Sofía, Guernica","url":"https://www.museoreinasofia.es/colecciones/obra/guernica","quote":"El motivo que impulsó a Pablo Picasso a realizar la escena representada en esta gran pintura fue la noticia de los bombardeos efectuados por la aviación alemana sobre la villa vasca que da nombre a la obra"}]},{"text":"L''Estat espanyol va adquirir el mural a Picasso el 1937. El 1958 Picasso va renovar el préstec del quadre al MoMA de Nova York per temps indefinit, fins que es restablissin les llibertats democràtiques a Espanya, i l''obra finalment va tornar al país el 1981. Avui es conserva al Museo Reina Sofía de Madrid.","refs":[{"ref":"Museo Reina Sofía","law":"Museo Reina Sofía, Guernica","url":"https://www.museoreinasofia.es/colecciones/obra/guernica","quote":"El mural «Guernica» fue adquirido a Picasso por el Estado español en 1937."},{"ref":"Museo Reina Sofía","law":"Museo Reina Sofía, Guernica","url":"https://www.museoreinasofia.es/colecciones/obra/guernica","quote":"En 1958 Picasso renovó el préstamo del cuadro al MoMA por tiempo indefinido, hasta que se restablecieran las libertades democráticas en España, regresando la obra finalmente a nuestro país en el año 1981."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Ordre dels estils: romànic (entre el preromànic i el gòtic), gòtic (del segle XII al Renaixement) i barroc (Itàlia, finals del XVI, fins a bona part del XVIII).","refs":[{"ref":"DIEC, barroc","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"aparegut a Itàlia a les darreries del segle xvi i predominant a Europa fins gran part del segle xviii."}]},{"text":"Absis: capçalera semicircular amb altar; rosassa: finestral circular gòtic; retaule: decoració d''un altar.","refs":[{"ref":"DIEC, rosassa","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Gran finestral circular, calat i vidrat, que es troba als murs de les esglésies gòtiques"}]},{"text":"Impressionisme: impressió immediata; cubisme: volum amb formes geomètriques; surrealisme: França, 1924.","refs":[{"ref":"DIEC, surrealisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Moviment literari, artístic i filosòfic, sorgit a França l’any 1924"}]},{"text":"Gaudí (1852-1926) és el màxim exponent del modernisme català; el 2026 és l''Any Gaudí.","refs":[{"ref":"Ajuntament de Barcelona","law":"Ajuntament de Barcelona, Any Gaudí","url":"https://ajuntament.barcelona.cat/premsa/2026/06/07/barcelona-ret-homenatge-a-antoni-gaudi-amb-una-placa-en-el-mateix-punt-on-va-ser-atropellat-lany-1926/","quote":"el màxim exponent del modernisme català"}]},{"text":"Set obres de Gaudí són patrimoni mundial des del 1984; el Palau de la Música i Sant Pau (1997) són de Domènech i Montaner.","refs":[{"ref":"UNESCO, fitxa 804","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"by the Catalan art nouveau architect Lluís Domènech i Montaner"}]},{"text":"Poblet (1991): abadia cistercenca amb el panteó dels reis de Catalunya i Aragó.","refs":[{"ref":"UNESCO, fitxa 518","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"contains the pantheon of the kings of Catalonia and Aragon"}]},{"text":"Machu Picchu: Imperi inca; Petra: nabateus; Taj Mahal: mausoleu de marbre blanc a Agra; Acròpoli: Pèricles i Fídies.","refs":[{"ref":"UNESCO, fitxa 274","law":"UNESCO, World Heritage List","url":"https://whc.unesco.org/en/list/","quote":"the most amazing urban creation of the Inca Empire at its height"}]},{"text":"Guernica: Picasso, 1937, Pavelló Espanyol de l''Exposició de París; va tornar a Espanya el 1981.","refs":[{"ref":"Museo Reina Sofía","law":"Museo Reina Sofía, Guernica","url":"https://www.museoreinasofia.es/colecciones/obra/guernica","quote":"regresando la obra finalmente a nuestro país en el año 1981."}]}]}]'::jsonb, (select id from public.sources where url = 'https://dlc.iec.cat/'), 'https://dlc.iec.cat/', null, null, null, 'Otras normas citadas: Museo Reina Sofía, Guernica (https://www.museoreinasofia.es/colecciones/obra/guernica), Ajuntament de Barcelona, Any Gaudí (https://ajuntament.barcelona.cat/premsa/2026/06/07/barcelona-ret-homenatge-a-antoni-gaudi-amb-una-placa-en-el-mateix-punt-on-va-ser-atropellat-lany-1926/), UNESCO, World Heritage List (https://whc.unesco.org/en/list/)'
  from public.topics t where t.slug = 'cultcat-04-art-patrimoni'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Patrimoni Cultural de la Generalitat de Catalunya: col·leccions (Jacint Verdaguer, Salvador Espriu, Joan Maragall, Josep Pla) i històries del patrimoni', 'https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya, Departament de Cultura (Patrimoni Cultural)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('cultcat-05-literatura', 'Cultura general 5. Literatura catalana, castellana i universal') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local', 'guardia-urbana-barcelona') and t.slug = 'cultcat-05-literatura' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Literatura catalana medieval: Tirant lo Blanc"},{"n":"2","title":"Renaixença, modernisme i noucentisme"},{"n":"3","title":"Autors catalans: Verdaguer, Maragall, Espriu, Pla"},{"n":"4","title":"Premis Nobel i Premi Cervantes"},{"n":"5","title":"Gèneres i formes: sonet i faula"}]'::jsonb, '["Tirant lo Blanc, autor Patrimoni.gencat: «El protagonista de la novela ''Tirant Lo Blanc'', obra del valenciano Joanot Martorell»","Verdaguer, Canigó Patrimoni.gencat: «va ser quan va escriure dos dels seus poemes més importants: L’Atlàntida (1877) i Canigó (1886)»","García Márquez, Nobel 1982 NobelPrize.org: «Gabriel García Márquez Nobel Prize in Literature 1982 Born: 6 March 1927, Aracataca, Colombia»","Renaixença DIEC2: «renaixença 2 f. [FLL] Moviment cultural vuitcentista promotor de la recuperació de la llengua i la literatura catalanes.»","Sonet DIEC2: «sonet 1 m. [FLL] [LC] Composició poètica formada per dos quartets amb dues soles rimes i dos tercets.»","Faula DIEC2: «faula 2 2 f. [FLL] [LC] Narració en què es dona un ensenyament útil o moral, per mitjà d’una ficció al·legòrica en què intervenen animals i àdhuc éssers inanimats parlant i obrant com si fossin éssers humans o racionals.»","Espriu, Sinera Patrimoni.gencat: «Aquest poble del Maresme va ser la seva “petita pàtria” i apareix mitificat en la seva obra com a Sinera (Arenys al revés).»","Josep Pla, Palafrugell Patrimoni.gencat: «Fill d’una família de petits propietaris rurals de Palafrugell, va estudiar dret a la Universitat de Barcelona.»","Joan Maragall Patrimoni.gencat: «Joan Maragall és una de les figures cabdals de la poesia modernista, tot i que també va cultivar la prosa.»","Verdaguer, Folgueroles Patrimoni.gencat: «Fill d’un mestre i pagès modest de Folgueroles (Osona), va ingressar al seminari de Vic el 1855.»","Tirant lo Blanc, Carmesina Patrimoni.gencat: «Carmesina es hija del emperador, y su doncella Plaerdemavida ayudará a Tirant Lo Blanc a conquistarla.»","Juan Ramón Jiménez, Nobel 1956 NobelPrize.org: «Juan Ramón Jiménez Nobel Prize in Literature 1956 Born: 24 December 1881, Moguer, Spain»","Cela, Nobel 1989 NobelPrize.org: «Camilo José Cela Nobel Prize in Literature 1989 Born: 11 May 1916, Iria Flavia, Spain»","Premi Cervantes Ministerio de Cultura, Premio Cervantes: «Puede ser galardonado con el Premio Cervantes cualquier autor o autora cuya obra literaria esté escrita totalmente, o en parte esencial, en castellano.»","Noucentisme DIEC2: «noucentisme m. [HIH] Moviment cultural d’abast polític iniciat a Catalunya a la primeria del segle xx.»","Espriu, La pell de brau Patrimoni.gencat: «La consagració va arribar amb La pell de Brau (1960), una al·legoria crítica amb l''Espanya de la postguerra»","Verdaguer, Jocs Florals Patrimoni.gencat: «amb només 20 anys, Jacint Verdaguer (1845 –1902) va guanyar els seus primers Jocs Florals i va anar a recollir el premi vestit de pagès.»","Vargas Llosa NobelPrize.org: «Mario Vargas Llosa Nobel Prize in Literature 2010 Born: 28 March 1936, Arequipa, Peru Died: 13 April 2025, Lima, Peru»","Joan Margarit, Premi Cervantes 2019 Ministerio de Cultura, Premio Cervantes: «2019 Joan Margarit»","Aleixandre, Nobel 1977 NobelPrize.org: «Vicente Aleixandre Nobel Prize in Literature 1977 Born: 26 April 1898, Sevilla, Spain»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Literatura catalana medieval: Tirant lo Blanc","blocks":[{"text":"Tirant lo Blanc és una novel·la escrita pel valencià Joanot Martorell. El protagonista, Tirant, s''enamora de la bella princesa Carmesina des del moment que la veu en arribar a Constantinoble. Carmesina és filla de l''emperador, i la seva donzella Plaerdemavida ajudarà Tirant a conquistar-la. Cal retenir, doncs, quatre noms: Martorell (l''autor), Tirant (l''heroi), Carmesina (l''estimada) i Plaerdemavida (la donzella que fa de mitjancera).","refs":[{"ref":"Patrimoni, «Una historia de amor»","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"El protagonista de la novela ''Tirant Lo Blanc'', obra del valenciano Joanot Martorell, se enamora de la bella princesa desde el momento en que la ve al llegar a Constantinopla."},{"ref":"Patrimoni, «Una historia de amor»","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Carmesina es hija del emperador, y su doncella Plaerdemavida ayudará a Tirant Lo Blanc a conquistarla."}]},{"text":"L''adjectiu cavalleresc, segons el DIEC, s''aplica al que té el caràcter i les qualitats del cavaller ideal, l''esperit de la cavalleria, com en l''expressió «ideals cavallerescos»; és l''adjectiu amb què se sol qualificar una novel·la protagonitzada per un cavaller com Tirant. Les fonts oficials carregades no indiquen la data de l''obra ni detallen altres autors medievals.","refs":[{"ref":"DIEC, cavalleresc","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"cavalleresc -a 3 adj. [FLL] [HIH] [LC] Que té el caràcter, les qualitats, del cavaller ideal, l’esperit de la cavalleria. Ideals cavallerescos."}]}]},{"n":"2","title":"La Renaixença","blocks":[{"text":"La Renaixença és el moviment cultural del segle XIX (vuitcentista) que va promoure la recuperació de la llengua i la literatura catalanes. No s''ha de confondre amb el Renaixement, que és el moviment cultural impulsat a Itàlia a partir del segle XIV, i després arreu d''Europa, per recuperar les idees i l''art de l''antiguitat grecoromana. La paraula semblant amaga dos moviments separats per segles.","refs":[{"ref":"DIEC, renaixença","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"renaixença 2 f. [FLL] Moviment cultural vuitcentista promotor de la recuperació de la llengua i la literatura catalanes."},{"ref":"DIEC, renaixement","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"renaixement 2 2 m. [HIH] [LC] Moviment cultural impulsat, a partir del segle xiv a Itàlia i després arreu d’Europa, per a la recuperació de les idees i l’art antic grecoromà."}]},{"text":"Amb aquest objectiu encaixa la figura de Jacint Verdaguer, de qui el Departament de Cultura diu que va tornar a situar la llengua catalana en la categoria de llengua literària (les fonts carregades no l''adscriuen explícitament a la Renaixença). Els seus primers èxits van arribar en els Jocs Florals (vegeu l''apartat 4).","refs":[{"ref":"Patrimoni, Jacint Verdaguer","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Verdaguer és una de les grans figures de la Catalunya moderna, que va torna a situar la llengua catalana en la categoria de llengua literària."}]}]},{"n":"3","title":"Modernisme i noucentisme","blocks":[{"text":"El modernisme és un moviment artístic, literari i arquitectònic desenvolupat a finals del segle XIX i principis del XX a l''Europa occidental i als Estats Units, caracteritzat per la voluntat de modernitat. En literatura, Joan Maragall és una de les figures cabdals de la poesia modernista, tot i que també va conrear la prosa.","refs":[{"ref":"DIEC, modernisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"modernisme 3 m. [AR] [FLL] Moviment artístic, literari i arquitectònic, que es desenvolupà al final del segle xix i al principi del segle xx a l’Europa occidental i als Estats Units, caracteritzat per la voluntat de modernitat."},{"ref":"Patrimoni, Joan Maragall","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Joan Maragall és una de les figures cabdals de la poesia modernista, tot i que també va cultivar la prosa."}]},{"text":"El noucentisme és un moviment cultural d''abast polític iniciat a Catalunya a la primeria del segle XX. L''ordre cronològic és, per tant: Renaixença (segle XIX), modernisme (final del XIX i principi del XX) i noucentisme (primeria del XX). Més endavant, autors com Salvador Espriu, Josep Pla i Josep Maria de Sagarra són considerats renovadors de la prosa catalana respecte de les fórmules noucentistes.","refs":[{"ref":"DIEC, noucentisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"noucentisme m. [HIH] Moviment cultural d’abast polític iniciat a Catalunya a la primeria del segle xx."},{"ref":"Patrimoni, Salvador Espriu","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"és considerat un dels renovadors, juntament amb Josep Pla i Josep Maria de Sagarra, de la prosa catalana de les fórmules noucentistes."}]}]},{"n":"4","title":"Jacint Verdaguer","blocks":[{"text":"Jacint Verdaguer (1845-1902) era fill d''un mestre i pagès modest de Folgueroles, a Osona, i va ingressar al seminari de Vic el 1855. Amb només 20 anys va guanyar els seus primers Jocs Florals, i no va deixar indiferent ningú quan va anar a recollir el premi vestit de pagès. Si va néixer el 1845, aquell primer premi correspon, aproximadament, al 1865.","refs":[{"ref":"Patrimoni, Jacint Verdaguer","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Fill d’un mestre i pagès modest de Folgueroles (Osona), va ingressar al seminari de Vic el 1855."},{"ref":"Patrimoni, Jacint Verdaguer","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"No va deixar indiferent a ningú quan, amb només 20 anys, Jacint Verdaguer (1845 –1902) va guanyar els seus primers Jocs Florals i va anar a recollir el premi vestit de pagès."}]},{"text":"Entre el 1877 i el 1893 va residir al Palau Moja i va freqüentar els ambients socials més elevats. En aquest període va escriure dos dels seus poemes més importants, L''Atlàntida (1877) i Canigó (1886), considerats l''expressió més genuïna de la seva producció.","refs":[{"ref":"Patrimoni, Jacint Verdaguer","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"En aquest període (1877-93), en què va residir al Palau Moja i va freqüentar els ambients socials més elevats, va ser quan va escriure dos dels seus poemes més importants: L’Atlàntida (1877) i Canigó (1886), l’expressió més genuïna de la seva producció."}]}]},{"n":"5","title":"Joan Maragall","blocks":[{"text":"Joan Maragall és una de les figures cabdals de la poesia modernista, i també va escriure prosa. A examen, la clau és associar Maragall amb el modernisme (no amb la Renaixença, que és l''època de Verdaguer, ni amb el noucentisme). Les fonts oficials carregades no recullen dates ni títols de les seves obres.","refs":[{"ref":"Patrimoni, Joan Maragall","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Joan Maragall és una de les figures cabdals de la poesia modernista, tot i que també va cultivar la prosa."}]}]},{"n":"6","title":"Salvador Espriu","blocks":[{"text":"Salvador Espriu (1913-1985) va ser poeta, dramaturg i novel·lista, i és considerat, amb Josep Pla i Josep Maria de Sagarra, un dels renovadors de la prosa catalana. Arenys, poble del Maresme, va ser la seva «petita pàtria» i apareix mitificat a la seva obra com a Sinera, que és «Arenys» llegit al revés.","refs":[{"ref":"Patrimoni, Salvador Espriu","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Poeta, dramaturg i novel·lista, Salvador Espriu (1913-1985) és considerat un dels renovadors, juntament amb Josep Pla i Josep Maria de Sagarra, de la prosa catalana de les fórmules noucentistes."},{"ref":"Patrimoni, Salvador Espriu","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Aquest poble del Maresme va ser la seva “petita pàtria” i apareix mitificat en la seva obra com a Sinera (Arenys al revés)."}]},{"text":"El seu primer volum de poemes, Cementiri de Sinera, no es va publicar fins al 1946. La consagració li va arribar amb La pell de brau (1960), una al·legoria crítica amb l''Espanya de la postguerra i amb la seva intransigència envers els diferents pobles de la península Ibèrica.","refs":[{"ref":"Patrimoni, Salvador Espriu","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"El seu primer volum de poemes, Cementiri de Sinera, no es va publicar fins el 1946."},{"ref":"Patrimoni, Salvador Espriu","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"La consagració va arribar amb La pell de Brau (1960), una al·legoria crítica amb l''Espanya de la postguerra i la seva intransigència amb els diferents pobles de la península Ibèrica."}]}]},{"n":"7","title":"Josep Pla","blocks":[{"text":"Josep Pla (1897-1981) és un referent de la literatura i del periodisme catalans, i el seu llegat literari continua plenament vigent. Era fill d''una família de petits propietaris rurals de Palafrugell i va estudiar dret a la Universitat de Barcelona. Com hem vist, se''l considera, amb Espriu i Sagarra, un dels renovadors de la prosa catalana. Les fonts carregades no en citen obres concretes.","refs":[{"ref":"Patrimoni, Josep Pla","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"El seu llegat literari, plenament vigent, ha convertit Josep Pla (1897 – 1981) en un referent en la literatura i el periodisme catalans."},{"ref":"Patrimoni, Josep Pla","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Fill d’una família de petits propietaris rurals de Palafrugell, va estudiar dret a la Universitat de Barcelona."}]}]},{"n":"8","title":"Premis Nobel de literatura en llengua castellana","blocks":[{"text":"Diversos autors en castellà han rebut el premi Nobel de literatura. Juan Ramón Jiménez, nascut a Moguer el 1881, el va rebre el 1956. Vicente Aleixandre, nascut a Sevilla el 1898, el 1977. Gabriel García Márquez, nascut a Aracataca (Colòmbia) el 1927, el 1982. Camilo José Cela, nascut a Iria Flavia el 1916, el 1989.","refs":[{"ref":"Nobel Prize, facts","law":"NobelPrize.org","url":"https://www.nobelprize.org/all-nobel-prizes-2025/","quote":"Juan Ramón Jiménez Nobel Prize in Literature 1956 Born: 24 December 1881, Moguer, Spain"},{"ref":"Nobel Prize, facts","law":"NobelPrize.org","url":"https://www.nobelprize.org/all-nobel-prizes-2025/","quote":"Vicente Aleixandre Nobel Prize in Literature 1977 Born: 26 April 1898, Sevilla, Spain"},{"ref":"Nobel Prize, facts","law":"NobelPrize.org","url":"https://www.nobelprize.org/all-nobel-prizes-2025/","quote":"Gabriel García Márquez Nobel Prize in Literature 1982 Born: 6 March 1927, Aracataca, Colombia"},{"ref":"Nobel Prize, facts","law":"NobelPrize.org","url":"https://www.nobelprize.org/all-nobel-prizes-2025/","quote":"Camilo José Cela Nobel Prize in Literature 1989 Born: 11 May 1916, Iria Flavia, Spain"}]},{"text":"Mario Vargas Llosa va néixer a Arequipa (Perú) el 28 de març de 1936, va rebre el Nobel de literatura el 2010 i va morir a Lima el 13 d''abril de 2025. Atenció a la trampa: va morir a Lima, però no hi va néixer.","refs":[{"ref":"Nobel Prize, facts","law":"NobelPrize.org","url":"https://www.nobelprize.org/all-nobel-prizes-2025/","quote":"Mario Vargas Llosa Nobel Prize in Literature 2010 Born: 28 March 1936, Arequipa, Peru Died: 13 April 2025, Lima, Peru"}]}]},{"n":"9","title":"Premis Nobel de literatura recents","blocks":[{"text":"Els darrers Nobel de literatura són útils per a les preguntes d''actualitat (dades consultades el novembre del 2026). El 2024 el va rebre la sud-coreana Han Kang, per una prosa poètica intensa que s''enfronta als traumes històrics; el 2025, l''autor hongarès László Krasznahorkai, i el 2026, l''autora canadenca Anne Carson, per una obra que dialoga de manera lúdica amb la tradició clàssica.","refs":[{"ref":"Nobel Prize 2024","law":"NobelPrize.org","url":"https://www.nobelprize.org/all-nobel-prizes-2025/","quote":"Nobel Prize in Literature 2024 Han Kang “for her intense poetic prose that confronts historical traumas and exposes the fragility of human life”"},{"ref":"Nobel Prize 2025","law":"NobelPrize.org","url":"https://www.nobelprize.org/all-nobel-prizes-2025/","quote":"The Nobel Prize in Literature for 2025 is awarded to the Hungarian author László Krasznahorkai"},{"ref":"Nobel Prize 2026","law":"NobelPrize.org, premis 2026","url":"https://www.nobelprize.org/all-nobel-prizes-2026/","quote":"The Nobel Prize in Literature 2026 has been awarded to the Canadian author Anne Carson “for her bold and inventive oeuvre that, in playful dialogue with the classical tradition, has created new forms for contemporary literature.”"}]}]},{"n":"10","title":"El Premi Cervantes","blocks":[{"text":"El Premi de Literatura en Llengua Castellana Miguel de Cervantes el concedeix el Ministeri de Cultura i està dotat amb 125.000 euros. Pot rebre''l qualsevol autor o autora l''obra literària del qual estigui escrita totalment, o en una part essencial, en castellà; per tant, el requisit és la llengua de l''obra, no la nacionalitat. El 2025 el va guanyar el mexicà Gonzalo Celorio, nascut a Ciutat de Mèxic el 1948.","refs":[{"ref":"Ministeri de Cultura, 03/11/2025","law":"Ministerio de Cultura, Premio Cervantes","url":"https://www.cultura.gob.es/actualidad/2025/11/251103-premio-cervantes-2025.html","quote":"Puede ser galardonado con el Premio Cervantes cualquier autor o autora cuya obra literaria esté escrita totalmente, o en parte esencial, en castellano."},{"ref":"Ministeri de Cultura, 03/11/2025","law":"Ministerio de Cultura, Premio Cervantes","url":"https://www.cultura.gob.es/actualidad/2025/11/251103-premio-cervantes-2025.html","quote":"El jurado del Premio de Literatura en Lengua Castellana Miguel de Cervantes ha otorgado a Gonzalo Celorio el Premio Cervantes 2025. Concedido por el Ministerio de Cultura, el galardón está dotado con 125.000 euros."},{"ref":"Ministeri de Cultura, 03/11/2025","law":"Ministerio de Cultura, Premio Cervantes","url":"https://www.cultura.gob.es/actualidad/2025/11/251103-premio-cervantes-2025.html","quote":"Gonzalo Celorio nació en la Ciudad de México en 1948."}]},{"text":"Alguns guanyadors del palmarès: Jorge Guillén (1976), Luis Rosales (1982), Rafael Alberti (1983), Miguel Delibes (1993), Mario Vargas Llosa (1994), Camilo José Cela (1995), Juan Marsé (2008), Ana María Matute (2010), Eduardo Mendoza (2016), Joan Margarit (2019), Luis Mateo Díez (2023) i Álvaro Pombo (2024). Joan Margarit, guanyador el 2019, és el poeta català de la llista. Cela i Vargas Llosa tenen tots dos premis: el Nobel (1989 i 2010) i el Cervantes (1995 i 1994).","refs":[{"ref":"Ministeri de Cultura, palmarès","law":"Ministerio de Cultura, Premio Cervantes","url":"https://www.cultura.gob.es/actualidad/2025/11/251103-premio-cervantes-2025.html","quote":"1976 Jorge Guillén 1982 Luis Rosales 1983 Rafael Alberti 1993 Miguel Delibes 1994 Mario Vargas Llosa 1995 Camilo José Cela 2008 Juan Marsé 2010 Ana María Matute 2016 Eduardo Mendoza 2019 Joan Margarit 2023 Luis Mateo Díez 2024 Álvaro Pombo 2025 Gonzalo Celorio"}]}]},{"n":"11","title":"Gèneres i formes: sonet, estrofa i faula","blocks":[{"text":"El sonet és una composició poètica formada per dos quartets, amb només dues rimes, i dos tercets. Com que un quartet té quatre versos i un tercet tres, el sonet té 4 + 4 + 3 + 3 = 14 versos. Cada un d''aquests grups és una estrofa: un grup de versos que forma una unitat i que es correspon mètricament amb altres grups semblants.","refs":[{"ref":"DIEC, sonet","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"sonet 1 m. [FLL] [LC] Composició poètica formada per dos quartets amb dues soles rimes i dos tercets."},{"ref":"DIEC, estrofa","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"estrofa 1 f. [FLL] [LC] Grup de versos que constitueixen una unitat i s’ordenen de manera que presenten una correspondència mètrica amb un altre o altres grups semblants."}]},{"text":"La faula és una narració que transmet un ensenyament útil o moral per mitjà d''una ficció al·legòrica en què intervenen animals, i fins i tot éssers inanimats, que parlen i actuen com si fossin persones. Hi apareix, doncs, la personificació, figura retòrica que atribueix qualitats humanes a animals, coses o conceptes.","refs":[{"ref":"DIEC, faula","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"faula 2 2 f. [FLL] [LC] Narració en què es dona un ensenyament útil o moral, per mitjà d’una ficció al·legòrica en què intervenen animals i àdhuc éssers inanimats parlant i obrant com si fossin éssers humans o racionals."},{"ref":"DIEC, personificació","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"personificació 2 f. [FLL] Figura retòrica que consisteix en l’atribució de qualitats humanes a animals, coses o conceptes."}]}]},{"n":"12","title":"Figures retòriques bàsiques","blocks":[{"text":"La metàfora consisteix a usar un mot que expressa literalment una cosa per expressar-ne una altra que s''hi assembla. La metonímia designa una cosa amb el nom d''una altra amb què té una relació necessària (l''efecte per la causa, el contingut pel continent, etc.). La hipèrbole substitueix el terme propi per un altre que n''exagera la designació, augmentant-la o reduint-la. L''al·literació repeteix un mateix so en mots consecutius o propers.","refs":[{"ref":"DIEC, metàfora","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"metàfora f. [FL] [FLL] [LC] Figura retòrica que consisteix a emprar un mot que expressa literalment una cosa per a expressar-ne una altra que té una certa semblança amb aquella."},{"ref":"DIEC, metonímia","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Figura retòrica que consisteix a designar una cosa amb el nom d’una altra amb la qual manté una relació necessària, com ara l’efecte per la causa, el contingut pel continent, etc., o viceversa."},{"ref":"DIEC, hipèrbole","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"hipèrbole 1 f. [FLL] [LC] Figura retòrica que consisteix a substituir el terme propi per un altre que n’augmenta o en redueix la designació d’una manera exagerada."},{"ref":"DIEC, al·literació","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"al·literació 1 f. [FL] [FLL] Figura retòrica que consisteix a repetir un mateix so en dos o més mots consecutius o situats a intervals curts."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Tirant lo Blanc és del valencià Joanot Martorell; Tirant s''enamora de Carmesina, ajudat per Plaerdemavida.","refs":[{"ref":"Patrimoni","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"obra del valenciano Joanot Martorell"}]},{"text":"Renaixença: segle XIX, recuperació del català; noucentisme: primeria del segle XX, d''abast polític.","refs":[{"ref":"DIEC, renaixença","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Moviment cultural vuitcentista promotor de la recuperació de la llengua i la literatura catalanes."}]},{"text":"Verdaguer (1845-1902), de Folgueroles: Jocs Florals amb 20 anys, L''Atlàntida (1877) i Canigó (1886).","refs":[{"ref":"Patrimoni","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"L’Atlàntida (1877) i Canigó (1886)"}]},{"text":"Maragall és figura cabdal de la poesia modernista.","refs":[{"ref":"Patrimoni","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Joan Maragall és una de les figures cabdals de la poesia modernista"}]},{"text":"Espriu: Sinera és Arenys al revés; consagració amb La pell de brau (1960).","refs":[{"ref":"Patrimoni","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"apareix mitificat en la seva obra com a Sinera (Arenys al revés)."}]},{"text":"Josep Pla (1897-1981) era fill de Palafrugell.","refs":[{"ref":"Patrimoni","law":"Patrimoni.gencat","url":"https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer","quote":"Fill d’una família de petits propietaris rurals de Palafrugell"}]},{"text":"Nobel en castellà: Juan Ramón Jiménez 1956, Aleixandre 1977, García Márquez 1982, Cela 1989, Vargas Llosa 2010 (nascut a Arequipa).","refs":[{"ref":"Nobel Prize","law":"NobelPrize.org","url":"https://www.nobelprize.org/all-nobel-prizes-2025/","quote":"Mario Vargas Llosa Nobel Prize in Literature 2010 Born: 28 March 1936, Arequipa, Peru"}]},{"text":"El Premi Cervantes premia obra escrita en castellà; Joan Margarit el va rebre el 2019.","refs":[{"ref":"Ministeri de Cultura","law":"Ministerio de Cultura, Premio Cervantes","url":"https://www.cultura.gob.es/actualidad/2025/11/251103-premio-cervantes-2025.html","quote":"2019 Joan Margarit"}]},{"text":"El sonet té dos quartets i dos tercets (14 versos); la faula ensenya una moral amb animals que parlen.","refs":[{"ref":"DIEC, sonet","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Composició poètica formada per dos quartets amb dues soles rimes i dos tercets."}]}]}]'::jsonb, (select id from public.sources where url = 'https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer'), 'https://patrimoni.gencat.cat/ca/coleccio/jacint-verdaguer', null, null, null, 'Otras normas citadas: NobelPrize.org (https://www.nobelprize.org/all-nobel-prizes-2025/), DIEC2 (https://dlc.iec.cat/), Ministerio de Cultura, Premio Cervantes (https://www.cultura.gob.es/actualidad/2025/11/251103-premio-cervantes-2025.html)'
