select t.id, 'ca', '[{"n":"1","title":"Categories gramaticals"},{"n":"2","title":"Formació de mots: sigles, acrònims, prefixos"},{"n":"3","title":"Relacions semàntiques: sinonímia, antonímia, homonímia"},{"n":"4","title":"Figures retòriques"},{"n":"5","title":"Fonètica i ortografia: diftong, dièresi, apòstrof, accentuació"}]'::jsonb, '["Metàfora DIEC2: «metàfora f. [FL] [FLL] [LC] Figura retòrica que consisteix a emprar un mot que expressa literalment una cosa per a expressar-ne una altra que té una certa semblança amb aquella.»","Sinònim DIEC2: «Els termes llevant i est són mots sinònims.»","Antònim DIEC2: «antònim -a 1 adj. [FL] [LC] Que té un significat directament oposat al d’un altre mot.»","Onomatopeia DIEC2: «onomatopeia 1 f. [FL] [LC] Formació de mots a partir de la imitació de sons naturals.»","Monosíl·lab DIEC2: «monosíl·lab -a 1 2 m. [FL] [FLL] [LC] Mot d’una sola síl·laba.»","Adjectiu qualificatiu DIEC2: «adjectiu qualificatiu Adjectiu que expressa alguna qualitat del substantiu amb què es relaciona i sovint en restringeix l’extensió.»","Sigla DIEC2: «sigla 3 1 f. [FL] [LC] Mot format per les lletres inicials dels components d’un sintagma o d’un compost, que manté les propietats sintàctiques i el significat del sintagma o del mot originals. La sigla IEC és la manera abreujada de referir-nos a l’Institut d’Estudis Catalans.»","Acrònim DIEC2: «Els mots boirum i cantautor són acrònims formats a partir de boira i fum i de cantant i autor, respectivament.»","Hipèrbole DIEC2: «hipèrbole 1 f. [FLL] [LC] Figura retòrica que consisteix a substituir el terme propi per un altre que n’augmenta o en redueix la designació d’una manera exagerada.»","Personificació DIEC2: «personificació 2 f. [FLL] Figura retòrica que consisteix en l’atribució de qualitats humanes a animals, coses o conceptes.»","Gentilici DIEC2: «gentilici 2 1 adj. [FL] [LC] Que denota la nació o la pàtria d’una persona. Adjectiu gentilici.»","Prefix DIEC2: «prefix 1 m. [FL] [LC] Afix que precedeix un radical o un mot.»","Apòstrof DIEC2: «apòstrof m. [FL] [LC] Signe gràfic consistent en una coma volada (’), que serveix per a assenyalar l’elisió d’algunes lletres.»","Dièresi DIEC2: «dièresi 1 2 f. [FL] [LC] Signe gràfic consistent en dos punts col·locats sobre una vocal (¨)»","Esdrúixol DIEC2: «esdrúixol -a adj. [FL] [FLL] [LC] Proparoxíton 1. La paraula fórmula és esdrúixola.»","Metonímia DIEC2: «metonímia f. [FL] [FLL] [LC] Figura retòrica que consisteix a designar una cosa amb el nom d’una altra amb la qual manté una relació necessària, com ara l’efecte per la causa, el contingut pel continent, etc., o viceversa.»","Homònim DIEC2: «La forma d’infinitiu dur i l’adjectiu masculí singular dur són mots homònims.»","Al·literació DIEC2: «al·literació 1 f. [FL] [FLL] Figura retòrica que consisteix a repetir un mateix so en dos o més mots consecutius o situats a intervals curts.»","Diftong DIEC2: «diftong 1 m. [FL] [LC] Grup fònic format per una vocal i una semivocal o semiconsonant pronunciades dins una mateixa síl·laba.»","Conjunció DIEC2: «conjunció 3 2 f. [FL] [LC] Categoria lèxica constituïda per mots invariables que relacionen dos mots o grups de mots d’idèntica funció sintàctica o bé dues oracions coordinades o subordinades.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Categories gramaticals variables: adjectiu i pronom","blocks":[{"text":"Les paraules d''una llengua s''agrupen en categories lèxiques (també dites categories gramaticals o parts de l''oració) segons la forma que tenen i la funció que fan a la frase. Una primera distinció útil és entre categories variables, que canvien de forma (gènere, nombre, persona), i categories invariables, que sempre es mantenen iguals. L''adjectiu és una categoria variable: es relaciona amb el substantiu i hi concorda, és a dir, n''adopta el gènere i el nombre. Per això diem «un arbre verd» però «unes fulles verdes». L''adjectiu pot aparèixer com a atribut («la casa és gran»), com a aposició o com a predicat.","refs":[{"ref":"DIEC, adjectiu","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"adjectiu 2 1 m. [FL] [LC] Categoria lèxica constituïda per mots que, en funció d’atribut, d’aposició o de predicat, es relacionen amb els substantius i hi concorden."}]},{"text":"Dins dels adjectius, el més habitual a l''examen és l''adjectiu qualificatiu, que expressa una qualitat del substantiu: a «un arbre verd», «verd» diu com és l''arbre. Segons el diccionari, sovint en restringeix l''extensió: «arbres verds» designa menys arbres que «arbres», perquè deixa fora els que no són verds. Un tipus especial és l''adjectiu gentilici, que indica la nació o la pàtria d''una persona, com «barceloní», «terrassenc», «català» o «francès». Si una pregunta demana com s''anomena l''adjectiu que indica la procedència, la resposta és «gentilici».","refs":[{"ref":"DIEC, adjectiu qualificatiu","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"adjectiu qualificatiu Adjectiu que expressa alguna qualitat del substantiu amb què es relaciona i sovint en restringeix l’extensió."},{"ref":"DIEC, gentilici","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"gentilici 2 1 adj. [FL] [LC] Que denota la nació o la pàtria d’una persona. Adjectiu gentilici."}]},{"text":"El pronom és una categoria generalment variable que no té un significat fix: el seu valor depèn de la situació o del text. Diem que té un «significat ocasional»: «ell» pot referir-se a qualsevol persona segons de qui parlem (relació díctica, quan assenyala algú present, o anafòrica, quan remet a un element ja dit). El pronom pot fer de substantiu, d''adjectiu o d''adverbi. En català es distingeixen els pronoms febles, sense accent propi i enganxats al verb (per exemple «el» a «el veig» o «-lo» a «veure-lo»), i els pronoms forts, accentuats, que poden fer de subjecte o de complement («ell», «nosaltres», «a mi»).","refs":[{"ref":"DIEC, pronom","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"pronom 1 m. [FL] [LC] Categoria lèxica constituïda per mots generalment variables, que poden tenir caràcter substantiu, adjectiu o adverbial i que presenten un significat ocasional, delimitat a partir de relacions díctiques o anafòriques."},{"ref":"DIEC, pronom feble i fort","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"4 [FL] pronom feble Pronom inaccentuat que va immediatament al davant o al darrere del verb. 5 [FL] pronom fort Pronom accentuat que ocupa la posició de subjecte o de complement."}]},{"text":"Relacionat amb l''estructura de l''oració, el verb «predicar» té en gramàtica un sentit tècnic: afirmar o negar alguna cosa del subjecte. A «la nit és freda», s''afirma del subjecte «la nit» que és freda. També convé conèixer el terme «exhortatiu», que s''aplica a les oracions o formes que impliquen una exhortació a fer o no fer alguna cosa, com «Anem-hi!» o «No hi entreu».","refs":[{"ref":"DIEC, predicar","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"predicar 3 v. tr. [FL] Afirmar o negar (alguna cosa) del subjecte d’una oració."},{"ref":"DIEC, exhortatiu","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"exhortatiu -iva adj. [FL] En gram., que implica exhortació a fer o no fer alguna cosa."}]}]},{"n":"2","title":"Categories gramaticals invariables: adverbi, preposició, conjunció i interjecció","blocks":[{"text":"L''adverbi és un mot invariable que modifica un verb («corre ràpidament»), un adjectiu («molt alt»), un altre adverbi («massa tard») o tota una oració («Potser plourà»). Es classifiquen pel significat: de lloc («aquí»), de temps («ahir»), de manera («bé») o de grau («molt»). No té ni gènere ni nombre: diem «ells corren ràpidament» i «ella corre ràpidament».","refs":[{"ref":"DIEC, adverbi","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"adverbi 1 m. [FL] [LC] Categoria lèxica constituïda per mots invariables que modifiquen un verb, un adjectiu, un altre adverbi o tota una oració. Adverbis de lloc, de temps, de manera, de grau."}]},{"text":"La preposició i la conjunció són també invariables i serveixen per relacionar elements, però ho fan de manera diferent. La preposició s''anteposa a un constituent, normalment nominal, i n''expressa la relació amb un altre: a «la casa de la Maria», «de» lliga «la Maria» amb «la casa»; altres exemples són «a», «amb», «per» o «sense». La conjunció, en canvi, uneix dos mots o grups de mots que fan la mateixa funció sintàctica, o bé dues oracions, ja siguin coordinades o subordinades. Són conjuncions «i», «o», «però» (coordinació) o «perquè», «que», «si» (subordinació). Truc d''examen: si el mot va davant d''un nom i l''introdueix, és preposició; si enllaça dues parts equivalents o dues oracions, és conjunció.","refs":[{"ref":"DIEC, preposició","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"preposició 2 1 f. [FL] Categoria lèxica constituïda per mots invariables que s’anteposen a un constituent sintàctic, normalment nominal, i expressen la relació gramatical que aquest constituent estableix amb un altre."},{"ref":"DIEC, conjunció","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"conjunció 3 2 f. [FL] [LC] Categoria lèxica constituïda per mots invariables que relacionen dos mots o grups de mots d’idèntica funció sintàctica o bé dues oracions coordinades o subordinades."}]},{"text":"La interjecció és un mot o una locució invariable que, tota sola, equival a una oració sencera. Serveix per expressar l''actitud del parlant (sorpresa, dolor, alegria: «ai!», «oh!»), per establir comunicació amb l''oient («ei!», «hola!») o per evocar un soroll o un moviment. Per aquest darrer ús, les interjeccions toquen de prop les onomatopeies, que veurem a l''apartat següent.","refs":[{"ref":"DIEC, interjecció","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"interjecció f. [FL] [LC] Mot o locució invariable que equival sintàcticament a una oració i expressa l’actitud del parlant, estableix una comunicació entre el parlant i l’oient o evoca un soroll o un moviment."}]}]},{"n":"3","title":"Formació de mots: prefixos i sufixos","blocks":[{"text":"Molts mots es formen afegint afixos a un radical. Si l''afix va al davant, és un prefix; si va al darrere, és un sufix. En «desfer», «des-» és un prefix que s''afegeix a «fer»; en «refer», el prefix és «re-». En «llibreter» o «llibreria», en canvi, les terminacions «-er» i «-eria» són sufixos. El diccionari precisa que el sufix pot anar seguit d''altres afixos: a «llibreries», després del sufix «-eria» encara hi ha la marca de plural «-s». Recorda la pregunta típica: «des-» a «desfer» és un prefix, no un sufix, ni un radical, ni una desinència.","refs":[{"ref":"DIEC, prefix","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"prefix 1 m. [FL] [LC] Afix que precedeix un radical o un mot."},{"ref":"DIEC, sufix","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"sufix 2 1 m. [FL] Afix que segueix un radical o un mot i que alhora pot estar seguit per altres afixos."}]}]},{"n":"4","title":"Formació de mots: sigles, acrònims i onomatopeies","blocks":[{"text":"La sigla és un mot format amb les lletres inicials dels components d''un sintagma o d''un compost. L''exemple que dona el mateix diccionari és IEC, forma abreujada d''Institut d''Estudis Catalans: I (Institut), E (Estudis), C (Catalans). La sigla conserva el significat i les propietats sintàctiques del sintagma original; per això diem «l''IEC ha publicat» igual que diríem «l''Institut ha publicat».","refs":[{"ref":"DIEC, sigla","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"sigla 3 1 f. [FL] [LC] Mot format per les lletres inicials dels components d’un sintagma o d’un compost, que manté les propietats sintàctiques i el significat del sintagma o del mot originals. La sigla IEC és la manera abreujada de referir-nos a l’Institut d’Estudis Catalans."}]},{"text":"L''acrònim també és un mot nou fet a partir d''uns altres, però no amb inicials, sinó encaixant o fusionant dos o més mots, almenys un dels quals s''ha escurçat. El diccionari en dona dos exemples: «boirum», de «boira» i «fum», i «cantautor», de «cantant» i «autor». La clau per distingir-los és aquesta: la sigla agafa només lletres inicials (IEC); l''acrònim retalla i enganxa trossos de mots (cant- + autor). Un compost com «paraigua» no és un acrònim, perquè uneix «para» i «aigua» sense escurçar-ne cap.","refs":[{"ref":"DIEC, acrònim","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"acrònim m. [FL] Mot format per l’encaix o la fusió de dos o més mots almenys un dels quals ha sofert una reducció. Els mots boirum i cantautor són acrònims formats a partir de boira i fum i de cantant i autor, respectivament."}]},{"text":"L''onomatopeia és la formació de mots imitant sons naturals, i el mateix nom designa també el mot que en resulta. Són onomatopeies «tic-tac» (el rellotge), «nyam-nyam» (menjar) o «xip-xap» (l''aigua). No s''ha de confondre amb l''al·literació, que és una figura retòrica de repetició de sons dins d''un text.","refs":[{"ref":"DIEC, onomatopeia","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"onomatopeia 1 f. [FL] [LC] Formació de mots a partir de la imitació de sons naturals. 2 f. [FL] Mot que resulta d’una onomatopeia."}]}]},{"n":"5","title":"Relacions semàntiques: sinonímia, antonímia, homonímia i polisèmia","blocks":[{"text":"Dos mots són sinònims quan tenen el mateix significat, encara que en una frase concreta puguin funcionar de manera una mica diferent. L''exemple del diccionari és la parella «llevant» i «est», que designen el mateix punt cardinal. En canvi, «llevant» i «ponent» o «est» i «oest» no són sinònims, sinó que designen direccions oposades.","refs":[{"ref":"DIEC, sinònim","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"sinònim -a 1 adj. [FL] [LC] Que té el mateix significat que un altre mot, encara que pugui diferir en altres valors funcionals dins un enunciat concret. Els termes llevant i est són mots sinònims."}]},{"text":"Els antònims són mots de significat directament oposat: «alt» i «baix», «obrir» i «tancar», «est» i «oest». És la relació contrària a la sinonímia, i a l''examen solen aparèixer juntes per confondre: mateix significat, sinònims; significat oposat, antònims.","refs":[{"ref":"DIEC, antònim","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"antònim -a 1 adj. [FL] [LC] Que té un significat directament oposat al d’un altre mot."}]},{"text":"Els homònims són mots que tenen exactament la mateixa forma però significats diferents. El diccionari posa l''exemple de «dur»: l''infinitiu «dur» (portar) i l''adjectiu «dur» (que no és tou) són dos mots diferents que s''escriuen igual. Cal distingir-ho de la polisèmia, que és la propietat d''una sola unitat lèxica de tenir més d''un significat: per exemple, «fulla» d''un arbre i «fulla» de paper es consideren sovint sentits d''un mateix mot. En resum: homonímia, dos mots iguals de forma; polisèmia, un sol mot amb diversos significats.","refs":[{"ref":"DIEC, homònim","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"homònim 2 1 adj. [FL] Que és formalment idèntic a un altre mot però té un significat diferent. La forma d’infinitiu dur i l’adjectiu masculí singular dur són mots homònims."},{"ref":"DIEC, polisèmia","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"polisèmia f. [FL] Propietat per la qual una unitat lèxica té més d’un significat."}]}]},{"n":"6","title":"Figures retòriques de significat: metàfora, metonímia, hipèrbole i personificació","blocks":[{"text":"Les figures retòriques són maneres d''usar el llenguatge que s''aparten de l''expressió directa per aconseguir un efecte. La metàfora consisteix a usar un mot que vol dir literalment una cosa per expressar-ne una altra que s''hi assembla. A «les perles de la teva boca» per dir «les dents», la semblança (blancor, brillantor) permet substituir un terme per l''altre. La metàfora es basa, doncs, en la semblança.","refs":[{"ref":"DIEC, metàfora","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"metàfora f. [FL] [FLL] [LC] Figura retòrica que consisteix a emprar un mot que expressa literalment una cosa per a expressar-ne una altra que té una certa semblança amb aquella."}]},{"text":"La metonímia també designa una cosa amb el nom d''una altra, però no per semblança, sinó perquè hi ha entre elles una relació necessària: l''efecte per la causa, el contingut pel continent, i viceversa. A «ens vam beure un got de vi» no ens bevem el got (continent), sinó el vi que conté: es nomena el continent pel contingut. Truc: si hi ha semblança, metàfora; si hi ha una relació real de proximitat o dependència, metonímia.","refs":[{"ref":"DIEC, metonímia","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"metonímia f. [FL] [FLL] [LC] Figura retòrica que consisteix a designar una cosa amb el nom d’una altra amb la qual manté una relació necessària, com ara l’efecte per la causa, el contingut pel continent, etc., o viceversa."}]},{"text":"La hipèrbole és l''exageració: substitueix el terme propi per un altre que augmenta o redueix desmesuradament allò que es diu. «T''ho he dit un milió de vegades» és una hipèrbole per augment; «no hi havia ni una ànima» o «espera''t un segon» poden ser-ho per reducció.","refs":[{"ref":"DIEC, hipèrbole","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"hipèrbole 1 f. [FLL] [LC] Figura retòrica que consisteix a substituir el terme propi per un altre que n’augmenta o en redueix la designació d’una manera exagerada."}]},{"text":"La personificació atribueix qualitats humanes a animals, coses o conceptes. A «el vent xiuxiuejava secrets a les finestres», el vent fa una acció pròpia de les persones. Aquest recurs és la base de la faula, una narració que dona un ensenyament útil o moral per mitjà d''una ficció en què animals i fins i tot éssers inanimats parlen i actuen com si fossin persones.","refs":[{"ref":"DIEC, personificació","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"personificació 2 f. [FLL] Figura retòrica que consisteix en l’atribució de qualitats humanes a animals, coses o conceptes."},{"ref":"DIEC, faula","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"faula 2 2 f. [FLL] [LC] Narració en què es dona un ensenyament útil o moral, per mitjà d’una ficció al·legòrica en què intervenen animals i àdhuc éssers inanimats parlant i obrant com si fossin éssers humans o racionals."}]}]},{"n":"7","title":"Figures de so i formes poètiques: al·literació, estrofa i sonet","blocks":[{"text":"L''al·literació és una figura de so: repeteix un mateix so en dos o més mots consecutius o propers. Un exemple propi seria «el riu rodola per les roques roges», on es repeteix el so de la erra. No s''ha de confondre amb l''onomatopeia (formació d''un mot que imita un so) ni amb la polisèmia (un mot amb diversos significats).","refs":[{"ref":"DIEC, al·literació","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"al·literació 1 f. [FL] [FLL] Figura retòrica que consisteix a repetir un mateix so en dos o més mots consecutius o situats a intervals curts."}]},{"text":"En poesia, l''estrofa és un grup de versos que formen una unitat i que es corresponen mètricament amb altres grups semblants. Una forma clàssica és el sonet, composició de dos quartets (estrofes de quatre versos) amb només dues rimes i dos tercets (estrofes de tres versos): en total, catorze versos.","refs":[{"ref":"DIEC, estrofa","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"estrofa 1 f. [FLL] [LC] Grup de versos que constitueixen una unitat i s’ordenen de manera que presenten una correspondència mètrica amb un altre o altres grups semblants."},{"ref":"DIEC, sonet","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"sonet 1 m. [FLL] [LC] Composició poètica formada per dos quartets amb dues soles rimes i dos tercets."}]}]},{"n":"8","title":"Fonètica: síl·laba, diftong i accentuació","blocks":[{"text":"Les paraules es divideixen en síl·labes. Un monosíl·lab és un mot d''una sola síl·laba, com «pa», «sol» o «mar». Quan una vocal i una semivocal o semiconsonant (una i o una u que s''hi recolzen) es pronuncien dins la mateixa síl·laba, formen un diftong: per exemple, «ai» a «mai», «au» a «pau» o «ua» a «quatre». Si les dues vocals es pronuncien en síl·labes diferents, com a «ve-ï-na», no hi ha diftong: és el que la gramàtica anomena hiat.","refs":[{"ref":"DIEC, monosíl·lab","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"monosíl·lab -a 1 2 m. [FL] [FLL] [LC] Mot d’una sola síl·laba."},{"ref":"DIEC, diftong","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"diftong 1 m. [FL] [LC] Grup fònic format per una vocal i una semivocal o semiconsonant pronunciades dins una mateixa síl·laba."}]},{"text":"Segons la posició de la síl·laba tònica (la que es pronuncia amb més força), els mots es classifiquen en aguts (tònica a la darrera síl·laba: «can-çó»), plans (a la penúltima: «tau-la») i esdrúixols o proparoxítons (a l''antepenúltima: «fór-mu-la»). El diccionari usa precisament «fórmula» com a exemple de mot esdrúixol. Per comptar, separa les síl·labes i compta des del final: fór (3a) - mu (2a) - la (1a).","refs":[{"ref":"DIEC, esdrúixol","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"esdrúixol -a adj. [FL] [FLL] [LC] Proparoxíton 1. La paraula fórmula és esdrúixola."}]}]},{"n":"9","title":"Ortografia: dièresi i apòstrof","blocks":[{"text":"La dièresi (¨) és un signe gràfic de dos punts damunt d''una vocal, que s''usa d''acord amb les normes ortogràfiques de cada llengua. En català la trobem, per exemple, a «pingüí», on indica que la u es pronuncia, i a «veïna», on indica que la i forma síl·laba a part i no fa diftong amb la vocal anterior.","refs":[{"ref":"DIEC, dièresi","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"dièresi 1 2 f. [FL] [LC] Signe gràfic consistent en dos punts col·locats sobre una vocal (¨), que s’usa d’acord amb les normes ortogràfiques de cada llengua."}]},{"text":"L''apòstrof (’) és una coma volada que assenyala que s''han elidit (suprimit) algunes lletres. A «l''home», l''article «el» perd la vocal davant d''un mot que comença per vocal o h; a «d''aigua», la preposició «de» perd la e. No l''has de confondre amb la dièresi (dos punts sobre una vocal), ni amb el guionet, que uneix els pronoms febles al verb («veure-lo»).","refs":[{"ref":"DIEC, apòstrof","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"apòstrof m. [FL] [LC] Signe gràfic consistent en una coma volada (’), que serveix per a assenyalar l’elisió d’algunes lletres."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Metàfora = semblança («les perles de la teva boca»); metonímia = relació necessària, com el continent pel contingut («beure un got»).","refs":[{"ref":"DIEC, metonímia","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"com ara l’efecte per la causa, el contingut pel continent, etc., o viceversa."}]},{"text":"Hipèrbole = exageració («un milió de vegades»); personificació = qualitats humanes a coses o animals («el vent xiuxiuejava»).","refs":[{"ref":"DIEC, hipèrbole","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"n’augmenta o en redueix la designació d’una manera exagerada."}]},{"text":"Al·literació = repetició d''un mateix so en mots consecutius o propers; onomatopeia = mot que imita un so natural («tic-tac»).","refs":[{"ref":"DIEC, al·literació","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"repetir un mateix so en dos o més mots consecutius o situats a intervals curts."}]},{"text":"Sigla = lletres inicials (IEC); acrònim = fusió de mots retallats (boirum, cantautor).","refs":[{"ref":"DIEC, acrònim","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Els mots boirum i cantautor són acrònims"}]},{"text":"Sinònims = mateix significat (llevant i est); antònims = significat oposat; homònims = mateixa forma i significat diferent (dur, verb, i dur, adjectiu).","refs":[{"ref":"DIEC, sinònim","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Els termes llevant i est són mots sinònims."}]},{"text":"El prefix va davant del radical («des-» a «desfer»); el sufix, darrere.","refs":[{"ref":"DIEC, prefix","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Afix que precedeix un radical o un mot."}]},{"text":"Conjunció = relaciona mots de la mateixa funció o oracions coordinades o subordinades («i», «però», «perquè»); preposició = va davant d''un constituent normalment nominal («de», «a», «amb»).","refs":[{"ref":"DIEC, conjunció","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"relacionen dos mots o grups de mots d’idèntica funció sintàctica o bé dues oracions coordinades o subordinades."}]},{"text":"Gentilici = adjectiu que indica la nació o la pàtria (barceloní, terrassenc); adjectiu qualificatiu = expressa una qualitat del substantiu.","refs":[{"ref":"DIEC, gentilici","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Que denota la nació o la pàtria d’una persona."}]},{"text":"Diftong = vocal + semivocal o semiconsonant dins la mateixa síl·laba; esdrúixol = tònica a l''antepenúltima («fórmula»); monosíl·lab = una sola síl·laba.","refs":[{"ref":"DIEC, esdrúixol","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"La paraula fórmula és esdrúixola."}]},{"text":"Apòstrof = coma volada que marca l''elisió de lletres («l''home»); dièresi = dos punts sobre una vocal («pingüí», «veïna»).","refs":[{"ref":"DIEC, apòstrof","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Signe gràfic consistent en una coma volada (’)"}]}]}]'::jsonb, (select id from public.sources where url = 'https://dlc.iec.cat/'), 'https://dlc.iec.cat/', null, null, null, null
  from public.topics t where t.slug = 'cultcat-06-llengua-catalana'
