insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-local', 'guardia-urbana-barcelona') and t.slug = 'cultcat-09-institucions-economia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Constitució espanyola: forma d''Estat, Corts i Tribunal Constitucional"},{"n":"2","title":"Estatut d''autonomia: capital, llengua, Parlament i President"},{"n":"3","title":"Sistema electoral (Idescat)"},{"n":"4","title":"Unió Europea i ONU"},{"n":"5","title":"Conceptes d''economia"}]'::jsonb, '["CE art. 1.3, forma política CE: «La forma política del Estado español es la Monarquía parlamentaria.»","EAC art. 10, capital EAC: «La capital de Cataluña es la ciudad de Barcelona, que es la sede permanente del Parlamento, de la Presidencia de la Generalitat y del Gobierno»","EAC art. 6.1, llengua pròpia EAC: «La lengua propia de Cataluña es el catalán.»","Inflació DIEC2: «inflació 2 1 f. [ECT] [LC] Increment generalitzat i persistent dels preus de les mercaderies i els serveis que implica una reducció del poder adquisitiu del diner.»","Euro DIEC2: «euro 1 m. [ECT] [LC] Unitat monetària comuna dels estats de la Unió Europea que participen en la unió econòmica i monetària.»","CE art. 66.1, Corts Generals CE: «Las Cortes Generales representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado.»","EAC art. 56.1, Parlament EAC: «El Parlamento se compone de un mínimo de cien Diputados y un máximo de ciento cincuenta, elegidos para un plazo de cuatro años»","Parlament de Catalunya, escons Idescat: «Total escons 2021 85 17 15 18 135»","Regla d''Hondt i llindar electoral Idescat: «Hi ha uns percentatges mínims (3% per a les eleccions al Parlament de Catalunya i a les legislatives i 5% per a les locals)»","CE art. 68.1, Congrés CE: «El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados»","CE art. 69.1, Senat CE: «El Senado es la Cámara de representación territorial.»","EAC art. 67.4, nomenament del president EAC: «El Presidente o Presidenta de la Generalitat es nombrado por el Rey.»","Comissió Europea european-union.europa.eu: «La Comisión Europea es el órgano ejecutivo, políticamente independiente, de la UE. Es la única instancia responsable de elaborar propuestas de nueva legislación europea»","Parlament Europeu european-union.europa.eu: «Es elegido directamente por los votantes de la UE cada cinco años.»","Consell de Seguretat de l''ONU un.org: «It has 15 Members (5 permanent and 10 non-permanent members).»","CE art. 159, Tribunal Constitucional CE: «Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres.»","CE art. 137, organització territorial CE: «El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan.»","Zona euro european-union.europa.eu: «Hoy en día, el euro (€) es la moneda oficial de 21 de los 27 países de la UE»","Andorra a l''ONU un.org: «Andorra Date of Admission: 28-07-1993»","Consell d''Europa Consell de la UE, presidència irlandesa 2026: «The Council of Europe is not an EU institution. It is a separate international organisation, founded in 1949, that promotes democracy, human rights, and the rule of law across its 46 member countries.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Constitució espanyola: estat social i democràtic i forma política","blocks":[{"text":"L''article 1 de la Constitució defineix Espanya com un estat social i democràtic de dret que té quatre valors superiors: la llibertat, la justícia, la igualtat i el pluralisme polític. La sobirania nacional resideix en el poble espanyol, del qual emanen els poders de l''Estat. La forma política de l''Estat és la monarquia parlamentària: el cap de l''Estat és un rei, però el poder polític el tenen les institucions elegides.","refs":[{"ref":"Art. 1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"España se constituye en un Estado social y democrático de Derecho, que propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político. […] La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado. […] La forma política del Estado español es la Monarquía parlamentaria."},{"ref":"DIEC, monarquia","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"monarquia 2 f. [HIH] [PO] En les democràcies contemporànies, forma de govern en què el cap de l’Estat és designat per dret d’herència. Monarquia parlamentària o constitucional."}]},{"text":"La Constitució es fonamenta en la unitat de la nació espanyola i, alhora, reconeix i garanteix el dret a l''autonomia de les nacionalitats i regions que la integren i la solidaritat entre totes (art. 2). El castellà és la llengua oficial de l''Estat, i les altres llengües espanyoles són també oficials a les comunitats autònomes respectives d''acord amb els seus estatuts (art. 3).","refs":[{"ref":"Art. 2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones que la integran y la solidaridad entre todas ellas."},{"ref":"Art. 3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El castellano es la lengua española oficial del Estado. […] Las demás lenguas españolas serán también oficiales en las respectivas Comunidades Autónomas de acuerdo con sus Estatutos."}]}]},{"n":"2","title":"La Corona","blocks":[{"text":"El Rei és el cap de l''Estat, símbol de la seva unitat i permanència; arbitra i modera el funcionament regular de les institucions i assumeix la representació més alta de l''Estat en les relacions internacionals (art. 56). La seva persona és inviolable i no està subjecta a responsabilitat; per això els seus actes han d''anar refrendats. Entre les seves funcions (art. 62) hi ha sancionar i promulgar les lleis, convocar i dissoldre les Corts, convocar referèndums, proposar el candidat a president del Govern i tenir el comandament suprem de les Forces Armades.","refs":[{"ref":"Art. 56.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones, asume la más alta representación del Estado español en las relaciones internacionales"},{"ref":"Art. 56.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La persona del Rey es inviolable y no está sujeta a responsabilidad. Sus actos estarán siempre refrendados"},{"ref":"Art. 62 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"a) Sancionar y promulgar las leyes. b) Convocar y disolver las Cortes Generales y convocar elecciones en los términos previstos en la Constitución. c) Convocar a referéndum en los casos previstos en la Constitución. d) Proponer el candidato a Presidente del Gobierno"},{"ref":"Art. 62.h CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"h) El mando supremo de las Fuerzas Armadas."}]}]},{"n":"3","title":"Les Corts Generals: Congrés i Senat","blocks":[{"text":"Les Corts Generals representen el poble espanyol i estan formades per dues cambres: el Congrés dels Diputats i el Senat (art. 66.1). Exerceixen la potestat legislativa, aproven els pressupostos de l''Estat i controlen l''acció del Govern; a més, són inviolables. Ningú no pot ser membre de les dues cambres alhora.","refs":[{"ref":"Art. 66 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Las Cortes Generales representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado. […] Las Cortes Generales ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno […] Las Cortes Generales son inviolables."},{"ref":"Art. 67.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Nadie podrá ser miembro de las dos Cámaras simultáneamente"}]},{"text":"El Congrés té entre un mínim de 300 i un màxim de 400 diputats, elegits per sufragi universal, lliure, igual, directe i secret. La circumscripció electoral és la província (Ceuta i Melilla, un diputat cadascuna), l''elecció segueix criteris de representació proporcional i el mandat és de quatre anys (art. 68).","refs":[{"ref":"Art. 68.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados, elegidos por sufragio universal, libre, igual, directo y secreto"},{"ref":"Art. 68.2 a 68.4 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La circunscripción electoral es la provincia. Las poblaciones de Ceuta y Melilla estarán representadas cada una de ellas por un Diputado. […] La elección se verificará en cada circunscripción atendiendo a criterios de representación proporcional. […] El Congreso es elegido por cuatro años."}]},{"text":"El Senat és la cambra de representació territorial (art. 69.1). A cada província s''hi elegeixen quatre senadors, Ceuta i Melilla n''elegeixen dos cadascuna, i les comunitats autònomes en designen, a més, un i un altre per cada milió d''habitants. També s''elegeix per quatre anys.","refs":[{"ref":"Art. 69 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Senado es la Cámara de representación territorial. […] En cada provincia se elegirán cuatro Senadores […] Las poblaciones de Ceuta y Melilla elegirán cada una de ellas dos Senadores. […] Las Comunidades Autónomas designarán además un Senador y otro más por cada millón de habitantes de su respectivo territorio."},{"ref":"Art. 69.6 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Senado es elegido por cuatro años."}]}]},{"n":"4","title":"El Govern","blocks":[{"text":"El Govern dirigeix la política interior i exterior, l''Administració civil i militar i la defensa de l''Estat, i exerceix la funció executiva i la potestat reglamentària (art. 97). Després de cada renovació del Congrés, el Rei proposa un candidat a la presidència; si el Congrés li dona la confiança per majoria absoluta, el Rei el nomena president. Si no, es torna a votar 48 hores després i n''hi ha prou amb la majoria simple (art. 99).","refs":[{"ref":"Art. 97 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado. Ejerce la función ejecutiva y la potestad reglamentaria"},{"ref":"Art. 99.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Si el Congreso de los Diputados, por el voto de la mayoría absoluta de sus miembros, otorgare su confianza a dicho candidato, el Rey le nombrará Presidente. De no alcanzarse dicha mayoría, se someterá la misma propuesta a nueva votación cuarenta y ocho horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple."}]}]},{"n":"5","title":"Tribunal Constitucional i organització territorial","blocks":[{"text":"El Tribunal Constitucional té 12 membres nomenats pel Rei: quatre a proposta del Congrés i quatre del Senat (per majoria de tres cinquens), dos del Govern i dos del Consell General del Poder Judicial (art. 159.1). Són juristes de reconeguda competència amb més de quinze anys d''exercici, designats per nou anys i renovats per terceres parts cada tres anys. El president del Tribunal el nomena el Rei entre els seus membres, per tres anys (art. 160). Comprova el càlcul: 4 + 4 + 2 + 2 = 12, i un terç de 12 són 4 magistrats renovats cada tres anys.","refs":[{"ref":"Art. 159.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey; de ellos, cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial."},{"ref":"Art. 159.2 i 159.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"juristas de reconocida competencia con más de quince años de ejercicio profesional. […] Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres."},{"ref":"Art. 160 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Presidente del Tribunal Constitucional será nombrado entre sus miembros por el Rey, a propuesta del mismo Tribunal en pleno y por un período de tres años."}]},{"text":"El Tribunal resol, entre altres, el recurs d''inconstitucionalitat contra lleis, el recurs d''empara per violació de drets i llibertats i els conflictes de competència entre l''Estat i les comunitats autònomes (art. 161).","refs":[{"ref":"Art. 161.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Del recurso de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley. […] Del recurso de amparo por violación de los derechos y libertades […] De los conflictos de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí."}]},{"text":"Territorialment, l''Estat s''organitza en municipis, províncies i les comunitats autònomes que es constitueixin, i totes aquestes entitats gaudeixen d''autonomia per gestionar els seus interessos (art. 137). Si una comunitat autònoma incompleix les seves obligacions o atempta greument contra l''interès general, el Govern, amb l''aprovació per majoria absoluta del Senat, pot adoptar les mesures necessàries per obligar-la-hi (art. 155).","refs":[{"ref":"Art. 137 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan. Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses."},{"ref":"Art. 155.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"con la aprobación por mayoría absoluta del Senado, podrá adoptar las medidas necesarias para obligar a aquélla al cumplimiento forzoso de dichas obligaciones"}]}]},{"n":"6","title":"Estatut d''autonomia: Catalunya, Generalitat, llengua i capital","blocks":[{"text":"Catalunya, com a nacionalitat, exerceix el seu autogovern constituïda en comunitat autònoma d''acord amb la Constitució i l''Estatut, que és la seva norma institucional bàsica (art. 1 EAC). La Generalitat és el sistema institucional en què s''organitza aquest autogovern i la integren el Parlament, la Presidència, el Govern i les altres institucions previstes (art. 2 EAC).","refs":[{"ref":"Art. 1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Cataluña, como nacionalidad, ejerce su autogobierno constituida en Comunidad Autónoma de acuerdo con la Constitución y con el presente Estatuto, que es su norma institucional básica."},{"ref":"Art. 2.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La Generalitat está integrada por el Parlamento, la Presidencia de la Generalitat, el Gobierno y las demás instituciones que establece el Capítulo V, del Título II."}]},{"text":"La llengua pròpia de Catalunya és el català (art. 6.1 EAC). El català és llengua oficial de Catalunya, i també ho és el castellà, llengua oficial de l''Estat; tothom té dret a usar les dues llengües oficials i els ciutadans de Catalunya tenen el dret i el deure de conèixer-les (art. 6.2 EAC). No confonguis «llengua pròpia» (només el català) amb «llengua oficial» (català i castellà).","refs":[{"ref":"Art. 6.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La lengua propia de Cataluña es el catalán."},{"ref":"Art. 6.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El catalán es la lengua oficial de Cataluña. También lo es el castellano, que es la lengua oficial del Estado español. Todas las personas tienen derecho a utilizar las dos lenguas oficiales y los ciudadanos de Cataluña el derecho y el deber de conocerlas."}]},{"text":"La capital de Catalunya és la ciutat de Barcelona, seu permanent del Parlament, de la Presidència de la Generalitat i del Govern, tot i que el Parlament i el Govern es poden reunir en altres llocs de Catalunya (art. 10 EAC). L''Aran és reconegut com a realitat occitana i el poble aranès exerceix l''autogovern mitjançant l''Estatut i el Conselh Generau d''Aran (art. 11 EAC).","refs":[{"ref":"Art. 10 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"La capital de Cataluña es la ciudad de Barcelona, que es la sede permanente del Parlamento, de la Presidencia de la Generalitat y del Gobierno, sin perjuicio de que el Parlamento y el Gobierno puedan reunirse en otros lugares de Cataluña"},{"ref":"Art. 11.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El pueblo aranés ejerce el autogobierno mediante el presente Estatuto, el Conselh Generau de Aran y las demás instituciones propias."}]}]},{"n":"7","title":"El Parlament i el President de la Generalitat","blocks":[{"text":"El Parlament representa el poble de Catalunya, exerceix la potestat legislativa, aprova els pressupostos de la Generalitat i controla i impulsa l''acció de govern (art. 55 EAC). Es compon d''un mínim de cent diputats i un màxim de cent cinquanta, elegits per quatre anys per sufragi universal, lliure, igual, directe i secret (art. 56.1 EAC). El sistema electoral és de representació proporcional i la llei electoral s''ha d''aprovar per majoria de dues terceres parts dels diputats (art. 56.2 EAC).","refs":[{"ref":"Art. 55 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El Parlamento representa al pueblo de Cataluña. […] El Parlamento ejerce la potestad legislativa, aprueba los presupuestos de la Generalitat y controla e impulsa la acción política y de gobierno."},{"ref":"Art. 56.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El Parlamento se compone de un mínimo de cien Diputados y un máximo de ciento cincuenta, elegidos para un plazo de cuatro años mediante sufragio universal, libre, igual, directo y secreto"},{"ref":"Art. 56.2 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El sistema electoral es de representación proporcional y debe asegurar la representación adecuada de todas las zonas del territorio de Cataluña. […] El régimen electoral es regulado por una ley del Parlamento aprobada en una votación final sobre el conjunto del texto por mayoría de dos terceras partes de los Diputados."}]},{"text":"El president o presidenta de la Generalitat té la representació més alta de la Generalitat, dirigeix l''acció del Govern i té també la representació ordinària de l''Estat a Catalunya (art. 67.1 EAC). L''elegeix el Parlament d''entre els seus membres i el nomena el Rei (art. 67.2 i 67.4 EAC). Si dos mesos després de la primera votació d''investidura no s''ha elegit ningú, el Parlament queda dissolt automàticament i es convoquen eleccions (art. 67.3 EAC). El Govern és l''òrgan col·legiat superior que dirigeix l''acció política i l''Administració de la Generalitat (art. 68 EAC).","refs":[{"ref":"Art. 67.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El Presidente o Presidenta tiene la más alta representación de la Generalitat y dirige la acción del Gobierno. También tiene la representación ordinaria del Estado en Cataluña."},{"ref":"Art. 67.2 i 67.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El Presidente o Presidenta de la Generalitat es elegido por el Parlamento de entre sus miembros. […] El Presidente o Presidenta de la Generalitat es nombrado por el Rey."},{"ref":"Art. 67.3 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"Si una vez transcurridos dos meses desde la primera votación de investidura, ningún candidato o candidata es elegido, el Parlamento queda disuelto automáticamente"},{"ref":"Art. 68.1 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El Gobierno es el órgano superior colegiado que dirige la acción política y la Administración de la Generalitat."}]}]},{"n":"8","title":"Sistema electoral (Idescat)","blocks":[{"text":"Segons les dades electorals d''Idescat de les eleccions al Parlament del 14 de febrer de 2021, el Parlament de Catalunya té 135 escons. La taula desglossa el total en 85, 17, 15 i 18 escons (el fragment carregat no reprodueix la capçalera de les columnes, per això no n''atribuïm cap a una circumscripció concreta). La xifra encaixa dins la forquilla de l''Estatut (entre 100 i 150). Comprova la suma: 85 + 17 + 15 + 18 = 135.","refs":[{"ref":"Idescat, Parlament de Catalunya 2021","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Parlament de Catalunya. 14 de febrer del 2021. Escons."},{"ref":"Idescat, Parlament de Catalunya 2021","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Total escons 2021 85 17 15 18 135"}]},{"text":"Els escons (al Parlament o els regidors als ajuntaments) es reparteixen segons la regla matemàtica d''Hondt. A més, hi ha un llindar mínim: els partits que no arriben al 3% dels vots a les eleccions al Parlament de Catalunya i a les legislatives, o al 5% a les locals, no entren en el repartiment d''escons. Recorda: 3% Parlament i Congrés, 5% municipals.","refs":[{"ref":"Idescat, Parlament de Catalunya 2021","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"La distribució d''escons (siguin escons al Parlament o regidors per als consistoris) es fa d''acord amb la regla matemàtica d''Hondt. Hi ha uns percentatges mínims (3% per a les eleccions al Parlament de Catalunya i a les legislatives i 5% per a les locals) per sota dels quals els partits o coalicions que no els hagin obtingut no entren en el repartiment d''escons."}]}]},{"n":"9","title":"La Unió Europea: institucions i euro","blocks":[{"text":"La Comissió Europea és l''òrgan executiu, políticament independent, de la UE: és l''única instància responsable d''elaborar propostes de nova legislació europea i aplica les decisions del Parlament Europeu i del Consell de la UE. La forma un col·legi de comissaris, un per país, i té la seu a Brussel·les; segons la font (6 de novembre de 2026), la presideix Ursula von der Leyen.","refs":[{"ref":"Comisión Europea","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"La Comisión Europea es el órgano ejecutivo, políticamente independiente, de la UE. Es la única instancia responsable de elaborar propuestas de nueva legislación europea y de aplicar las decisiones del Parlamento Europeo y del Consejo de la UE."},{"ref":"Comisión Europea","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Un equipo («colegio») de comisarios, uno por cada país de la UE Presidencia: Ursula von der Leyen Año de creación: 1958 Sede: Bruselas (Bélgica)"}]},{"text":"El Parlament Europeu és l''òrgan legislatiu de la UE i l''elegeixen directament els votants cada cinc anys; les darreres eleccions van ser del 6 al 9 de juny de 2024. Té 720 eurodiputats i la presideix Roberta Metsola (dada de la font de novembre de 2026). Les seus són Estrasburg, Brussel·les i Luxemburg.","refs":[{"ref":"Parlamento Europeo","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"El Parlamento Europeo es el órgano legislativo de la UE. Es elegido directamente por los votantes de la UE cada cinco años. Las elecciones europeas más recientes tuvieron lugar del 6 al 9 de junio de 2024."},{"ref":"Parlamento Europeo","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Miembros: 720 eurodiputados (diputados al Parlamento Europeo) Presidenta: Roberta Metsola"},{"ref":"Parlamento Europeo","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Sede: Estrasburgo (Francia), Bruselas (Bélgica), Luxemburgo"}]},{"text":"El Consell Europeu, format pels caps d''estat o de govern, defineix les orientacions polítiques generals però no negocia ni adopta lleis; el presideix António Costa. El Consell de la UE reuneix ministres de cada país segons el tema, i la presidència rota cada sis mesos: Irlanda l''exerceix de l''1 de juliol al 31 de desembre de 2026, dins un trio amb Lituània i Grècia.","refs":[{"ref":"Consejo Europeo","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Define las orientaciones y prioridades políticas generales de la Unión Europea Miembros: Jefes de Estado o de Gobierno de los países de la UE, presidente del Consejo Europeo, presidenta de la Comisión Europea Presidente: António Costa"},{"ref":"Presidència irlandesa","law":"Consell de la UE, presidència irlandesa 2026","url":"https://irish-presidency.consilium.europa.eu/en/presidency/presidency-of-the-council-of-the-eu/","quote":"It sets the EU''s overall political direction and priorities, but does not negotiate or adopt EU laws."},{"ref":"Presidència irlandesa","law":"Consell de la UE, presidència irlandesa 2026","url":"https://irish-presidency.consilium.europa.eu/en/presidency/presidency-of-the-council-of-the-eu/","quote":"Ireland holds the Presidency from 1 July until 31 December 2026."},{"ref":"Presidència irlandesa","law":"Consell de la UE, presidència irlandesa 2026","url":"https://irish-presidency.consilium.europa.eu/en/presidency/presidency-of-the-council-of-the-eu/","quote":"Ireland is currently part of a trio presidency with Lithuania and Greece."}]},{"text":"L''euro és la moneda oficial de 21 dels 27 països de la UE, que formen la zona euro (dada de 2026; Bulgària hi va entrar l''1 de gener de 2026). Dinamarca es va acollir a una clàusula per mantenir la seva moneda. Espanya és membre de la UE des de 1986 i de la zona euro des de 1999. Les condicions per adoptar l''euro es van acordar el 1992 al Tractat de Maastricht.","refs":[{"ref":"Países que usan el euro","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Hoy en día, el euro (€) es la moneda oficial de 21 de los 27 países de la UE, que juntos constituyen la eurozona, denominada oficialmente zona del euro."},{"ref":"Bulgaria (ficha de país)","law":"european-union.europa.eu, fitxes de país","url":"https://european-union.europa.eu/principles-countries-history/eu-countries_es","quote":"Zona del euro: Miembro desde el 1 de enero de 2026"},{"ref":"Países que usan el euro","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Dinamarca se ha acogido a esta cláusula para la moneda única y ha mantenido su propia moneda tras su adhesión a la UE."},{"ref":"Países de la UE","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"España Estado miembro de la UE desde 1986, miembro de la zona del euro desde 1999"},{"ref":"Países que usan el euro","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Estas condiciones económicas y jurídicas de obligado cumplimiento se acordaron en 1992 a través del Tratado de Maastricht."}]},{"text":"Compte amb el Consell d''Europa: no és una institució de la UE, sinó una organització internacional separada, fundada el 1949, que promou la democràcia, els drets humans i l''estat de dret entre els seus 46 estats membres.","refs":[{"ref":"Presidència irlandesa","law":"Consell de la UE, presidència irlandesa 2026","url":"https://irish-presidency.consilium.europa.eu/en/presidency/presidency-of-the-council-of-the-eu/","quote":"The Council of Europe is not an EU institution. It is a separate international organisation, founded in 1949, that promotes democracy, human rights, and the rule of law across its 46 member countries."}]}]},{"n":"10","title":"Les Nacions Unides","blocks":[{"text":"L''ONU té actualment 193 estats membres. Els estats hi són admesos per decisió de l''Assemblea General a recomanació del Consell de Seguretat; per exemple, Andorra hi va ser admesa el 28 de juliol de 1993. El Consell de Seguretat té la responsabilitat principal de mantenir la pau i la seguretat internacionals i té 15 membres: 5 de permanents i 10 de no permanents.","refs":[{"ref":"ONU, About us","law":"un.org","url":"https://www.un.org/en/about-us","quote":"Currently made up of 193 Member States"},{"ref":"ONU, Member states","law":"un.org","url":"https://www.un.org/en/about-us","quote":"States are admitted to membership by a decision of the General Assembly upon the recommendation of the Security Council."},{"ref":"ONU, Member states","law":"un.org","url":"https://www.un.org/en/about-us","quote":"Andorra Date of Admission: 28-07-1993"},{"ref":"ONU, Main bodies","law":"un.org","url":"https://www.un.org/en/about-us","quote":"The Security Council has primary responsibility, under the UN Charter, for the maintenance of international peace and security. It has 15 Members (5 permanent and 10 non-permanent members)."}]},{"text":"El secretari general és António Guterres (font del 6 de novembre de 2026). El procés per seleccionar-ne el successor es va iniciar formalment amb una carta conjunta dels presidents de l''Assemblea General i del Consell de Seguretat publicada el 25 de novembre de 2025. Les fonts carregades no indiquen quins estats són els cinc membres permanents.","refs":[{"ref":"ONU","law":"un.org","url":"https://www.un.org/en/about-us","quote":"António Guterres United Nations Secretary-General"},{"ref":"ONU, SG selection","law":"un.org","url":"https://www.un.org/en/about-us","quote":"A joint letter of the President of the General Assembly and the President of the Security Council addressed to Member States, published on 25 November 2025, formally initiated the selection process."}]}]},{"n":"11","title":"Conceptes bàsics d''economia (DIEC)","blocks":[{"text":"La inflació és l''increment generalitzat i persistent dels preus de les mercaderies i els serveis, que implica una reducció del poder adquisitiu dels diners: amb els mateixos euros es poden comprar menys coses. L''euro és la unitat monetària comuna dels estats de la UE que participen en la unió econòmica i monetària.","refs":[{"ref":"DIEC, inflació","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"inflació 2 1 f. [ECT] [LC] Increment generalitzat i persistent dels preus de les mercaderies i els serveis que implica una reducció del poder adquisitiu del diner."},{"ref":"DIEC, euro","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"euro 1 m. [ECT] [LC] Unitat monetària comuna dels estats de la Unió Europea que participen en la unió econòmica i monetària."}]},{"text":"El pressupost és el còmput anticipat de les despeses i els ingressos d''una entitat per a un període determinat; el dèficit és allò que manca perquè els ingressos arribin a cobrir les despeses. Per exemple, si una entitat preveu gastar 100 i ingressar-ne 90, té un dèficit de 10. L''atur és la desocupació forçosa i involuntària per manca d''oferta de feina.","refs":[{"ref":"DIEC, pressupost","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"pressupost 1 m. [AD] [ECT] [LC] Còmput anticipat del que costarà una obra a fer, de les despeses i els ingressos d’una entitat per a un període de temps determinat."},{"ref":"DIEC, dèficit","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"dèficit 1 m. [ECT] [LC] Allò que manca perquè els ingressos pugin tant com les despeses"},{"ref":"DIEC, atur","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"atur m. [ECT] [LC] [SO] Desocupació forçosa, involuntària, per manca d’oferta de col·locació."}]},{"text":"La hipoteca és el dret que es dona per contracte a un creditor, com a garantia, sobre una propietat del deutor sense que se''n transfereixi la possessió. La borsa és el lloc públic on es reuneixen els agents de canvi i on es negocien els valors mobiliaris admesos a cotització. El capitalisme és el sistema econòmic caracteritzat per la propietat privada dels mitjans de producció, la prevalença del mercat i la recerca del benefici. Un percentatge és un tant per cent: el 3% vol dir 3 de cada 100.","refs":[{"ref":"DIEC, hipoteca","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"hipoteca 1 f. [DR] [ECT] [LC] Dret donat per contracte com a garantia a un creditor sobre una propietat del deutor sense transferència de possessió."},{"ref":"DIEC, borsa","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"borsa 1 f. [ECT] [LC] Lloc públic on es reuneixen els agents de canvi, on es negocien els valors mobiliaris admesos a cotització."},{"ref":"DIEC, capitalisme","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"capitalisme 1 m. [ECT] [LC] [SO] Sistema econòmic caracteritzat per la propietat privada dels mitjans de producció, concentrats en mans d’una minoria, la prevalença del mercat i la recerca del benefici."},{"ref":"DIEC, percentatge","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"percentatge m. [LC] [MT] Tant per cent."}]}]},{"n":"12","title":"Economia pública i dades recents","blocks":[{"text":"La Constitució encarrega al Govern elaborar els pressupostos generals de l''Estat i a les Corts examinar-los, esmenar-los i aprovar-los; són anuals i, si no s''aproven abans del primer dia de l''exercici, es prorroguen automàticament els de l''any anterior (art. 134). Totes les administracions s''han d''ajustar al principi d''estabilitat pressupostària (art. 135).","refs":[{"ref":"Art. 134 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Corresponde al Gobierno la elaboración de los Presupuestos Generales del Estado y a las Cortes Generales, su examen, enmienda y aprobación. […] Los Presupuestos Generales del Estado tendrán carácter anual […] se considerarán automáticamente prorrogados los Presupuestos del ejercicio anterior hasta la aprobación de los nuevos."},{"ref":"Art. 135.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Todas las Administraciones Públicas adecuarán sus actuaciones al principio de estabilidad presupuestaria."}]},{"text":"Dades d''actualitat (caduquen): el 27 de febrer de 2026 el Govern de la Generalitat va aprovar el projecte de pressupostos per al 2026, amb un import rècord de 49.162 milions d''euros, un 22,8% més que els del 2023, els darrers aprovats. Els departaments amb més pressupost eren Salut, Educació i Formació Professional i Drets Socials i Inclusió. Segons la Moncloa (16 de febrer de 2026), el salari mínim interprofessional ha passat de 735 euros mensuals el 2018 a 1.221 euros bruts al mes en 14 pagues el 2026.","refs":[{"ref":"Govern, nota de 27 de febrer de 2026","law":"Govern.cat, Pressupostos 2026","url":"https://govern.cat/salapremsa/notes-premsa/795676/pressupostos-generalitat-al-2026-creixen-228-percent-respecte-als-darrers-aprovats-acceleren-inversio-fons-propis","quote":"El Govern de la Generalitat ha aprovat avui el Projecte de llei de pressupostos per a l’any 2026, uns comptes ambiciosos que assoleixen un import rècord de 49.162 M€."},{"ref":"Govern, nota de 27 de febrer de 2026","law":"Govern.cat, Pressupostos 2026","url":"https://govern.cat/salapremsa/notes-premsa/795676/pressupostos-generalitat-al-2026-creixen-228-percent-respecte-als-darrers-aprovats-acceleren-inversio-fons-propis","quote":"que superen en un 22,8% (+9.126 M€) l’import dels pressupostos del 2023, els darrers aprovats."},{"ref":"Govern, nota de 27 de febrer de 2026","law":"Govern.cat, Pressupostos 2026","url":"https://govern.cat/salapremsa/notes-premsa/795676/pressupostos-generalitat-al-2026-creixen-228-percent-respecte-als-darrers-aprovats-acceleren-inversio-fons-propis","quote":"L’any 2026, els departaments que compten amb un pressupost més alt són Salut (13.840 M€), Educació i Formació Professional (8.356 M€) i Drets Socials i Inclusió (4.248 M€)."},{"ref":"La Moncloa, 16 de febrer de 2026","law":"La Moncloa, SMI 2026","url":"https://www.lamoncloa.gob.es/presidente/actividades/Paginas/2026/160226-sanchez-subida-salario-minimo.aspx","quote":"al pasar de los 735 euros al mes a los 1.221 euros brutos al mes en 14 pagas este año"}]},{"text":"Segons la portada d''Idescat del 6 de novembre de 2026, Catalunya tenia 8.237.683 habitants, una taxa d''atur del 8,30%, un creixement del PIB del 2,9% i un IPC del 4,5%. El PIB va créixer un 2,9% interanual i un 0,7% intertrimestral al tercer trimestre de 2026, segons l''estimació avançada.","refs":[{"ref":"Idescat, portada","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Estadística oficial de Catalunya 8.237.683 Població 8,30 % Atur +2,9 % PIB +4,5 % IPC"},{"ref":"Idescat, portada","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"El producte interior brut de Catalunya registra una variació interanual del 2,9% i intertrimestral del 0,7% al tercer trimestre del 2026, segons l''estimació avançada."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Forma política de l''Estat: monarquia parlamentària (art. 1.3 CE).","refs":[{"ref":"Art. 1.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La forma política del Estado español es la Monarquía parlamentaria."}]},{"text":"Corts Generals = Congrés (300-400 diputats) + Senat (cambra de representació territorial).","refs":[{"ref":"Art. 68.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados"}]},{"text":"Tribunal Constitucional: 12 membres, designats per nou anys, renovats per terços cada tres.","refs":[{"ref":"Art. 159.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"se renovarán por terceras partes cada tres."}]},{"text":"Organització territorial: municipis, províncies i comunitats autònomes (art. 137 CE).","refs":[{"ref":"Art. 137 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"en municipios, en provincias y en las Comunidades Autónomas que se constituyan."}]},{"text":"Estatut: capital Barcelona; llengua pròpia el català; Parlament de 100 a 150 diputats; el president el nomena el Rei.","refs":[{"ref":"Art. 67.4 EAC","law":"EAC","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087","quote":"El Presidente o Presidenta de la Generalitat es nombrado por el Rey."}]},{"text":"Parlament de Catalunya: 135 escons; regla d''Hondt; llindar del 3% (5% a les locals).","refs":[{"ref":"Idescat","law":"Idescat","url":"https://www.idescat.cat/indicadors/?id=aec&lang=ca","quote":"Hi ha uns percentatges mínims (3% per a les eleccions al Parlament de Catalunya i a les legislatives i 5% per a les locals)"}]},{"text":"UE: la Comissió és l''executiu i l''única que proposa lleis; el Parlament Europeu s''elegeix cada cinc anys; l''euro, a 21 dels 27 estats (2026).","refs":[{"ref":"Parlamento Europeo","law":"european-union.europa.eu","url":"https://european-union.europa.eu/index_es","quote":"Es elegido directamente por los votantes de la UE cada cinco años."}]},{"text":"ONU: Consell de Seguretat de 15 membres (5 permanents); Andorra, admesa el 1993.","refs":[{"ref":"ONU","law":"un.org","url":"https://www.un.org/en/about-us","quote":"It has 15 Members (5 permanent and 10 non-permanent members)."}]},{"text":"Consell d''Europa: no és de la UE; fundat el 1949; 46 estats.","refs":[{"ref":"Consell d''Europa","law":"Consell de la UE, presidència irlandesa 2026","url":"https://irish-presidency.consilium.europa.eu/en/presidency/presidency-of-the-council-of-the-eu/","quote":"It is a separate international organisation, founded in 1949"}]},{"text":"Inflació: pujada generalitzada i persistent dels preus que fa perdre poder adquisitiu als diners.","refs":[{"ref":"DIEC, inflació","law":"DIEC2","url":"https://dlc.iec.cat/","quote":"Increment generalitzat i persistent dels preus de les mercaderies i els serveis que implica una reducció del poder adquisitiu del diner."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: EAC (https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087), DIEC2 (https://dlc.iec.cat/), Idescat (https://www.idescat.cat/indicadors/?id=aec&lang=ca), european-union.europa.eu (https://european-union.europa.eu/index_es), un.org (https://www.un.org/en/about-us), Consell de la UE, presidència irlandesa 2026 (https://irish-presidency.consilium.europa.eu/en/presidency/presidency-of-the-council-of-the-eu/)'
  from public.topics t where t.slug = 'cultcat-09-institucions-economia'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);

-- Publicar de nuevo las fichas como titular (el cambio de contenido las devolvió a revisión)
do $$
declare
  v_owner uuid;
  v_slug text;
  v_n int := 0;
begin
  select id into v_owner from public.profiles
   where role = 'owner' and status = 'active' order by created_at limit 1;
  if v_owner is null then
    raise notice 'No hay persona titular: no se publica nada.';
    return;
  end if;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);

  for v_slug in select t.slug from public.topics t
                  join public.topic_notes n on n.topic_id = t.id
                 where (t.slug like 'cultcat-%' or t.slug like 'actcat-%') and n.status <> 'published'
                 order by t.slug loop
    perform public.review_topic_notes(v_slug, 'approved');
    v_n := v_n + public.review_topic_notes(v_slug, 'published');
  end loop;

  perform public.log_admin_action('content.publish_notes', 'exam_bodies',
    'policia-local,guardia-urbana-barcelona',
    jsonb_build_object('notes', v_n,
                       'motivo', 'Petición expresa de joel en el hilo del proyecto (10/11/2026: apuntes completos por tema, también en cultura general y actualidad)'));
  perform set_config('request.jwt.claims', '', true);
  raise notice 'Cultura general y actualidad de Cataluña: % fichas con apuntes publicadas', v_n;
end $$;

commit;
